// ---- Cari No Perjanjian (Master Data Nasabah) + preview info nasabah --------
const searchQuery = ref('')
const searchOpen = ref(false)
const searching = ref(false)
const searchResults = ref([])
let searchTimer = null

const preview = reactive({
	nama_nasabah: '',
	nopol: '',
	no_mesin: '',
	angsuran: null,
	angsuran_ke: '',
	tanggal_jto: '',
})
const previewLoading = ref(false)
const previewRows = computed(() => [
	{ label: 'Nama Nasabah', value: preview.nama_nasabah || '—' },
	{ label: 'Nopol', value: preview.nopol || '—' },
	{ label: 'No Mesin', value: preview.no_mesin || '—' },
	{
		label: 'Angsuran',
		value: preview.angsuran != null ? formatCurrency(preview.angsuran) : '—',
	},
	{ label: 'Angsuran ke', value: preview.angsuran_ke || '—' },
	{ label: 'Tanggal JTO', value: preview.tanggal_jto ? formatDate(preview.tanggal_jto) : '—' },
])

function onSearchFocus() {
	searchOpen.value = true
	if (!searchResults.value.length) fetchNasabah('')
}
function onSearch() {
	searchOpen.value = true
	clearTimeout(searchTimer)
	searchTimer = setTimeout(() => fetchNasabah(searchQuery.value), 300)
}
async function fetchNasabah(q) {
	searching.value = true
	try {
		const params = {
			doctype: 'Master Data Nasabah',
			fields: JSON.stringify(['name', 'nama_nasabah']),
			order_by: 'modified desc',
			limit_page_length: 20,
		}
		const t = (q || '').trim()
		if (t)
			params.or_filters = JSON.stringify([
				['name', 'like', `%${t}%`],
				['nama_nasabah', 'like', `%${t}%`],
			])
		searchResults.value = (await call('frappe.client.get_list', params)) || []
	} catch (e) {
		searchResults.value = []
	} finally {
		searching.value = false
	}
}
function resetPreview() {
	preview.nama_nasabah = ''
	preview.nopol = ''
	preview.no_mesin = ''
	preview.angsuran = null
	preview.angsuran_ke = ''
	preview.tanggal_jto = ''
}
async function selectNasabah(r) {
	form.no_perjanjian = r.name
	searchQuery.value = r.name
	searchOpen.value = false
	closeError.value = ''
	// Fetch info nasabah + JTO/angsuran ke (read-only, authoritative dari server).
	previewLoading.value = true
	resetPreview()
	try {
		const mdn = await call('frappe.client.get_value', {
			doctype: 'Master Data Nasabah',
			filters: r.name,
			fieldname: JSON.stringify(['nama_nasabah', 'nopol', 'mesin', 'angsuran']),
		})
		preview.nama_nasabah = mdn?.nama_nasabah || r.nama_nasabah || ''
		preview.nopol = mdn?.nopol || ''
		preview.no_mesin = mdn?.mesin || ''
		preview.angsuran = mdn?.angsuran ?? null
		const tr = await call('frappe.client.get_value', {
			doctype: 'Target dan Realisasi',
			filters: JSON.stringify({ no_perjanjian: r.name }),
			fieldname: JSON.stringify(['jto_tertunggak', 'angsuran_ke']),
		})
		preview.tanggal_jto = tr?.jto_tertunggak || ''
		preview.angsuran_ke = tr?.angsuran_ke || ''
	} catch (e) {
		/* preview gagal → biarkan '—'; server tetap fetch ulang saat submit */
	} finally {
		previewLoading.value = false
	}
}

