// ---- Kalender custom (Tanggal Pembayaran) ----------------------------------
const showDateSheet = ref(false)
const calCursor = ref(new Date()) // bulan tampil (tgl 1)
const WEEKDAYS = ['Sen', 'Sel', 'Rab', 'Kam', 'Jum', 'Sab', 'Min']
const MONTHS = [
	'Januari',
	'Februari',
	'Maret',
	'April',
	'Mei',
	'Juni',
	'Juli',
	'Agustus',
	'September',
	'Oktober',
	'November',
	'Desember',
]
function ymd(d) {
	const m = String(d.getMonth() + 1).padStart(2, '0')
	const day = String(d.getDate()).padStart(2, '0')
	return `${d.getFullYear()}-${m}-${day}`
}
function parseYmd(s) {
	const [y, m, d] = String(s).split('-').map(Number)
	return new Date(y, (m || 1) - 1, d || 1)
}
const calLabel = computed(
	() => `${MONTHS[calCursor.value.getMonth()]} ${calCursor.value.getFullYear()}`
)
const calDays = computed(() => {
	const year = calCursor.value.getFullYear()
	const month = calCursor.value.getMonth()
	const first = new Date(year, month, 1)
	const startOffset = (first.getDay() + 6) % 7 // Senin = 0
	const daysInMonth = new Date(year, month + 1, 0).getDate()
	const cells = []
	for (let i = 0; i < startOffset; i++) cells.push(null)
	for (let d = 1; d <= daysInMonth; d++) cells.push(new Date(year, month, d))
	return cells
})
function prevMonth() {
	calCursor.value = new Date(calCursor.value.getFullYear(), calCursor.value.getMonth() - 1, 1)
}
function nextMonth() {
	calCursor.value = new Date(calCursor.value.getFullYear(), calCursor.value.getMonth() + 1, 1)
}
function dayClass(date) {
	const s = ymd(date)
	if (s === form.tanggal_pembayaran) return 'rounded-full bg-primary font-semibold text-white'
	if (s === ymd(new Date())) return 'rounded-full font-semibold text-primary'
	return 'rounded-full text-gray-700 hover:bg-gray-100'
}
function openDatePicker() {
	const base = form.tanggal_pembayaran || ymd(new Date())
	const d = parseYmd(base)
	calCursor.value = new Date(d.getFullYear(), d.getMonth(), 1)
	showDateSheet.value = true
}
function pickDay(date) {
	form.tanggal_pembayaran = ymd(date)
	showDateSheet.value = false
}

function pickFile() {
	fileInput.value?.click()
}
function onFileChange(e) {
	const f = e.target.files?.[0]
	if (!f) return
	const MAX_MB = 3
	if (f.size > MAX_MB * 1024 * 1024) {
		closeError.value = `Ukuran file maksimal ${MAX_MB} MB.`
		pickedFile.value = null
	} else {
		closeError.value = ''
		pickedFile.value = f
	}
	e.target.value = '' // izinkan pilih file sama lagi
}

// Upload 1 file → kembalikan file_url. Endpoint Frappe standar (butuh CSRF).
async function uploadRawFile(file) {
	const fd = new FormData()
	fd.append('file', file, file.name)
	fd.append('is_private', '1')
	const res = await fetch('/api/method/upload_file', {
		method: 'POST',
		credentials: 'include',
		headers: { Accept: 'application/json', 'X-Frappe-CSRF-Token': window.csrf_token || '' },
		body: fd,
	})
	const json = await res.json().catch(() => ({}))
	if (!res.ok) throw new Error(json?.exception || json?.message || `HTTP ${res.status}`)
	return json.message?.file_url
}

async function submitClose() {
	if (!selectedType.value || submitting.value) return
	closeError.value = ''

	// Validasi client per tipe (server tetap validasi ulang).
	if (selectedType.value === 'Dipakai') {
		if (!form.no_perjanjian.trim()) return (closeError.value = 'No Perjanjian wajib diisi.')
		if (!form.nominal_bayar) return (closeError.value = 'Nominal Bayar wajib diisi.')
		if (!form.tanggal_pembayaran) return (closeError.value = 'Tanggal Pembayaran wajib diisi.')
	} else if (!pickedFile.value) {
		return (closeError.value =
			selectedType.value === 'Rusak'
				? 'Foto bukti wajib diunggah.'
				: 'Dokumen STPL wajib diunggah.')
	}

	submitting.value = true
	try {
		const args = { nomor_tts: name.value, tipe_close: selectedType.value }
		if (form.keterangan.trim()) args.keterangan = form.keterangan.trim()
		if (selectedType.value === 'Dipakai') {
			args.no_perjanjian = form.no_perjanjian.trim()
			args.nominal_bayar = form.nominal_bayar
			args.tanggal_pembayaran = form.tanggal_pembayaran
		} else {
			const fileUrl = await uploadRawFile(pickedFile.value)
			if (!fileUrl) throw new Error('Upload file gagal.')
			if (selectedType.value === 'Rusak') args.foto_rusak = fileUrl
			else args.dokumen_stpl = fileUrl
		}
		const r = await call('juragan.collection.doctype.tts.tts.close_tts', args)
		closeOpen.value = false
		doc.fetch() // refresh status → tombol Close hilang bila sudah pindah state
		autoToast('success', r?.message || 'Close TTS berhasil.')
	} catch (e) {
		closeError.value =
			e?.messages?.[0] || e?.message || String(e) || 'Gagal melakukan Close TTS.'
	} finally {
		submitting.value = false
	}
}

