/**
 * State global untuk viewer GAMBAR in-app (lightbox full-screen).
 *
 * Di aplikasi native, `window.open('_blank')` selalu membuka Safari eksternal
 * (dan URL relatif `/files/...` tidak valid di origin lokal). Karena itu lampiran
 * gambar ditampilkan di dalam app lewat overlay ini — gambar diambil sebagai blob
 * (via fetch yang sudah di-shim: absolut ke backend + header token).
 */
import { reactive } from 'vue'

export const imageState = reactive({
	open: false,
	url: '',
	title: '',
})

export function openImage(url, title = '') {
	imageState.url = url
	imageState.title = title || String(url).split('/').pop() || 'Gambar'
	imageState.open = true
}

export function closeImage() {
	imageState.open = false
	imageState.url = ''
	imageState.title = ''
}
