<script setup>
import { computed, nextTick, onBeforeUnmount, onMounted, reactive, ref, watch } from 'vue'
import { useRoute } from 'vue-router'
import { call, createResource, toast } from 'frappe-ui'
import { refreshCsrfToken } from '../data/session'
import { currentUser } from '../data/user'
import { openAttachment } from '../composables/pdfViewer'
import SelectMenu from '../components/SelectMenu.vue'

const route = useRoute()
const name = computed(() => String(route.params.name || ''))

// Kembali ke list dengan mempertahankan filter status bila ada (?status=).
const backTo = computed(() => ({
	name: 'TargetRealisasi',
	query: route.query.status ? { status: route.query.status } : undefined,
}))

// ===== Input Aktivitas (Field / Desk Collection) =====
// Tombol muncul sesuai role: Field Coll → Field; Desk Coll → Desk. Admin keduanya.
const isAdmin = computed(
	() =>
		currentUser.user === 'Administrator' ||
		(currentUser.roles || []).includes('System Manager')
)
const canFieldColl = computed(
	() => isAdmin.value || (currentUser.roles || []).includes('Field Coll')
)
const canDeskColl = computed(
	() => isAdmin.value || (currentUser.roles || []).includes('Desk Coll')
)

// Toast frappe-ui tak auto-dismiss di webview → hapus manual.
function autoToast(type, message) {
	const id = toast[type](message)
	setTimeout(() => toast.remove(id), 3500)
}

const aktivitasOpen = ref(false)
const aktivitasJenis = ref('') // 'field' | 'desk'
const aktivitasSubmitting = ref(false)
const aktivitasError = ref('')
const opts = reactive({ status: [], action: [], child: [] })

function blankAktForm() {
	return {
		tanggal_kunjungan: '',
		detail_case: '',
		status_nasabah: '',
		case_category: '',
		action: '',
		status_telpon: '',
		telpon_by: '',
		tanggal_janji_bayar: '',
	}
}
const form = reactive(blankAktForm())

const fotoInput = ref(null)
const fotoFile = ref(null)
const fotoName = computed(() => fotoFile.value?.name || '')

function todayStr() {
	const d = new Date()
	return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(
		d.getDate()
	).padStart(2, '0')}`
}

// Tanggal "dd Mmm yyyy" untuk tampilan tombol.
function fmtDateShort(v) {
	const d = new Date(String(v).replace(' ', 'T'))
	if (Number.isNaN(d.getTime())) return String(v)
	return d.toLocaleDateString('id-ID', { day: '2-digit', month: 'short', year: 'numeric' })
}

// Label read-only "Tanggal Telpon" (desk) = waktu saat modal dibuka.
const tanggalTelponLabel = ref('')

// ---- Kalender custom (field tanggal aktivitas) -----------------------------
const showDateSheet = ref(false)
const calTarget = ref('tanggal_kunjungan') // key di `form` yang sedang diedit
const calTitle = ref('')
const calCursor = ref(new Date())
const WEEKDAYS = ['Sen', 'Sel', 'Rab', 'Kam', 'Jum', 'Sab', 'Min']
const MONTHS = [
	'Januari',
	'Februari',
	'Maret',
	'April',
	'Mei',
	'Juni',
	'Juli',
	'Agustus',
	'September',
	'Oktober',
	'November',
	'Desember',
]
function ymd(d) {
	const m = String(d.getMonth() + 1).padStart(2, '0')
	const day = String(d.getDate()).padStart(2, '0')
	return `${d.getFullYear()}-${m}-${day}`
}
function parseYmd(s) {
	const [y, m, d] = String(s).split('-').map(Number)
	return new Date(y, (m || 1) - 1, d || 1)
}
const calLabel = computed(
	() => `${MONTHS[calCursor.value.getMonth()]} ${calCursor.value.getFullYear()}`
)
const calDays = computed(() => {
	const year = calCursor.value.getFullYear()
	const month = calCursor.value.getMonth()
	const first = new Date(year, month, 1)
	const startOffset = (first.getDay() + 6) % 7
	const daysInMonth = new Date(year, month + 1, 0).getDate()
	const cells = []
	for (let i = 0; i < startOffset; i++) cells.push(null)
	for (let d = 1; d <= daysInMonth; d++) cells.push(new Date(year, month, d))
	return cells
})
function prevMonth() {
	calCursor.value = new Date(calCursor.value.getFullYear(), calCursor.value.getMonth() - 1, 1)
}
function nextMonth() {
	calCursor.value = new Date(calCursor.value.getFullYear(), calCursor.value.getMonth() + 1, 1)
}
function dayClass(date) {
	const s = ymd(date)
	if (s === form[calTarget.value]) return 'rounded-full bg-primary font-semibold text-white'
	if (s === ymd(new Date())) return 'rounded-full font-semibold text-primary'
	return 'rounded-full text-gray-700 hover:bg-gray-100'
}
function openDatePicker(target, title) {
	calTarget.value = target
	calTitle.value = title
	const base = form[target] || ymd(new Date())
	const d = parseYmd(base)
	calCursor.value = new Date(d.getFullYear(), d.getMonth(), 1)
	showDateSheet.value = true
}
function pickDay(date) {
	form[calTarget.value] = ymd(date)
	showDateSheet.value = false
}
function clearDate() {
	form[calTarget.value] = ''
	showDateSheet.value = false
}

async function openAktivitas(jenis) {
	aktivitasJenis.value = jenis
	Object.assign(form, blankAktForm())
	if (jenis === 'field') form.tanggal_kunjungan = todayStr()
	if (jenis === 'desk')
		tanggalTelponLabel.value = new Date().toLocaleString('id-ID', {
			day: '2-digit',
			month: 'short',
			year: 'numeric',
			hour: '2-digit',
			minute: '2-digit',
		})
	fotoFile.value = null
	aktivitasError.value = ''
	opts.status = []
	opts.action = []
	opts.child = []
	aktivitasOpen.value = true
	try {
		const o = await call('juragan.api.portal.target_realisasi.get_aktivitas_options', {
			jenis,
		})
		opts.status = o?.status || []
		opts.action = o?.action || []
		opts.child = o?.child || []
	} catch (e) {
		/* opsi gagal → biarkan kosong, user tetap bisa isi field wajib */
	}
}
function closeAktivitas() {
	aktivitasOpen.value = false
}

// Opsi turunan (Case Category / Telpon By) ikut status terpilih.
async function fetchChildOptions(parent) {
	opts.child = []
	if (!parent) return
	try {
		const o = await call('juragan.api.portal.target_realisasi.get_aktivitas_options', {
			jenis: aktivitasJenis.value,
			parent,
		})
		opts.child = o?.child || []
	} catch (e) {
		/* biarkan kosong */
	}
}
watch(
	() => form.status_nasabah,
	(v) => {
		if (aktivitasJenis.value !== 'field') return
		form.case_category = ''
		fetchChildOptions(v)
	}
)
watch(
	() => form.status_telpon,
	(v) => {
		if (aktivitasJenis.value !== 'desk') return
		form.telpon_by = ''
		fetchChildOptions(v)
	}
)

function pickFoto() {
	fotoInput.value?.click()
}
function onFoto(e) {
	const f = e.target.files?.[0]
	if (!f) return
	if (f.size > 3 * 1024 * 1024) {
		aktivitasError.value = 'Ukuran foto maksimal 3 MB.'
		fotoFile.value = null
	} else {
		aktivitasError.value = ''
		fotoFile.value = f
	}
	e.target.value = ''
}
async function uploadRawFile(file) {
	const fd = new FormData()
	fd.append('file', file, file.name)
	fd.append('is_private', '1')
	const res = await fetch('/api/method/upload_file', {
		method: 'POST',
		credentials: 'include',
		headers: { Accept: 'application/json', 'X-Frappe-CSRF-Token': window.csrf_token || '' },
		body: fd,
	})
	const json = await res.json().catch(() => ({}))
	if (!res.ok) throw new Error(json?.exception || json?.message || `HTTP ${res.status}`)
	return json.message?.file_url
}

async function submitAktivitas() {
	if (aktivitasSubmitting.value) return
	aktivitasError.value = ''
	if (!form.detail_case.trim()) return (aktivitasError.value = 'Detail Case wajib diisi.')
	if (aktivitasJenis.value === 'field' && !form.tanggal_kunjungan)
		return (aktivitasError.value = 'Tanggal Kunjungan wajib diisi.')

	aktivitasSubmitting.value = true
	try {
		const payload = {
			detail_case: form.detail_case.trim(),
			tanggal_janji_bayar: form.tanggal_janji_bayar || null,
		}
		if (aktivitasJenis.value === 'field') {
			payload.tanggal_kunjungan = form.tanggal_kunjungan
			payload.status_nasabah = form.status_nasabah || null
			payload.case_category = form.case_category || null
			payload.action = form.action || null
			if (fotoFile.value) payload.foto_kunjungan = await uploadRawFile(fotoFile.value)
		} else {
			payload.status_telpon = form.status_telpon || null
			payload.telpon_by = form.telpon_by || null
		}
		await call('juragan.api.portal.target_realisasi.insert_aktivitas', {
			name: name.value,
			jenis: aktivitasJenis.value,
			payload: JSON.stringify(payload),
		})
		aktivitasOpen.value = false
		riwayatRes.fetch() // riwayat aktivitas ikut ter-refresh
		autoToast('success', 'Aktivitas berhasil disimpan')
	} catch (e) {
		aktivitasError.value =
			e?.messages?.[0] || e?.message || String(e) || 'Gagal menyimpan aktivitas.'
	} finally {
		aktivitasSubmitting.value = false
	}
}

// Susunan section + field (read-only). fmt: cara format nilai.
// Tab detail (gaya sama spt Data Pengajuan, ikon + label): hanya Data & Riwayat.
const TABS = [
	{
		key: 'data',
		label: 'Data',
		icon: '<rect x="3" y="3" width="18" height="18" rx="2"/><path d="M3 9h18"/><path d="M9 21V9"/>',
	},
	{
		key: 'riwayat',
		label: 'Riwayat Cek Aktivitas',
		icon: '<path d="M22 12h-4l-3 9L9 3l-3 9H2"/>',
	},
	{
		key: 'detail_nasabah',
		label: 'Detail Nasabah',
		icon: '<path d="M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2"/><circle cx="9" cy="7" r="4"/><path d="M22 21v-2a4 4 0 0 0-3-3.87"/><path d="M16 3.13a4 4 0 0 1 0 7.75"/>',
	},
	{
		key: 'attachment',
		label: 'Attachment',
		icon: '<path d="m21.44 11.05-9.19 9.19a6 6 0 0 1-8.49-8.49l8.57-8.57A4 4 0 1 1 18 8.84l-8.59 8.57a2 2 0 0 1-2.83-2.83l8.49-8.48"/>',
	},
]
const activeTab = ref('data')

// ===== Tab Attachment: attachment Data Pengajuan tertaut (READ-ONLY) =====
// Relasi: TR.no_perjanjian → Master Data Nasabah → register_id → Data Pengajuan
// (fallback: cocokkan Data Pengajuan lewat no_perjanjian). Di Target dan Realisasi
// attachment HANYA bisa dilihat/diunduh — tidak ada upload/hapus/edit.
const attach = reactive({
	loading: true,
	error: '',
	dpName: null,
	shareloc: '', // field Shareloc (URL) dari Data Pengajuan
