/**
 * Intersep klik link `target="_blank"` saat berjalan di aplikasi native.
 *
 * Di iOS/Android WKWebView Capacitor, `<a target="_blank">` (dan window.open)
 * SELALU membuka browser eksternal — pengguna "terlempar keluar" dari app.
 * Interceptor ini menangkap klik pada link semacam itu dan mengarahkannya ke
 * viewer in-app (PDF/gambar via openAttachment) sehingga tetap di dalam app.
 *
 * Di browser biasa (bukan native) tidak dipasang → perilaku tab-baru normal.
 */
import { isNativeApp } from './mobile'
import { openAttachment } from '../composables/pdfViewer'

export function initNativeLinks() {
	if (!isNativeApp() || typeof document === 'undefined') return

	document.addEventListener(
		'click',
		(e) => {
			const target = e.target
			const anchor = target && target.closest ? target.closest('a[target="_blank"]') : null
			if (!anchor) return
			const href = anchor.getAttribute('href')
			if (!href || href === '#' || href.toLowerCase().startsWith('javascript:')) {
				return
			}
			// Tangani in-app: cegah pindah ke Safari.
			e.preventDefault()
			openAttachment(href, (anchor.textContent || '').trim())
		},
		true // fase capture: dahului handler lain
	)
}
