/**
 * Utilitas mode native (Capacitor) + autentikasi berbasis token.
 *
 * Saat SPA dibundel LOKAL di dalam aplikasi (origin `https://localhost`),
 * panggilan API ke server produksi menjadi lintas-site. Cookie sesi tidak bisa
 * dipakai (iOS WKWebView/ITP memblokirnya), jadi autentikasi memakai token
 * Frappe (`Authorization: token api_key:api_secret`) yang disimpan di device.
 *
 * Di browser biasa (bukan native) semua fungsi ini pasif: `isNativeApp()`
 * false → app tetap berjalan same-origin dengan cookie seperti biasa.
 */

// Host backend produksi. Semua request path-relatif (`/api/...`, `/files/...`)
// dari bundel lokal diarahkan ke sini oleh shim fetch.
export const API_BASE = 'https://app.juragansejati.biz.id'

const TOKEN_KEY = 'juragan_mobile_token' // "api_key:api_secret"
const USER_KEY = 'juragan_mobile_user'
const FULLNAME_KEY = 'juragan_mobile_fullname'

/** True hanya saat berjalan di dalam aplikasi Capacitor (Android/iOS). */
export function isNativeApp() {
	return !!(
		typeof window !== 'undefined' &&
		window.Capacitor &&
		window.Capacitor.isNativePlatform &&
		window.Capacitor.isNativePlatform()
	)
}

/** Token tersimpan ("api_key:api_secret") atau null. */
export function getToken() {
	try {
		return window.localStorage.getItem(TOKEN_KEY) || null
	} catch (e) {
		return null
	}
}

export function setAuth({ api_key, api_secret, user, full_name }) {
	try {
		if (api_key && api_secret) {
			window.localStorage.setItem(TOKEN_KEY, api_key + ':' + api_secret)
		}
		if (user) window.localStorage.setItem(USER_KEY, user)
		if (full_name) window.localStorage.setItem(FULLNAME_KEY, full_name)
	} catch (e) {
		/* localStorage tidak tersedia — abaikan */
	}
}

export function clearAuth() {
	try {
		window.localStorage.removeItem(TOKEN_KEY)
		window.localStorage.removeItem(USER_KEY)
		window.localStorage.removeItem(FULLNAME_KEY)
	} catch (e) {
		/* abaikan */
	}
}

/** User id tersimpan dari login terakhir (untuk boot sebelum verifikasi server). */
export function storedUser() {
	try {
		return window.localStorage.getItem(USER_KEY) || null
	} catch (e) {
		return null
	}
}
