									<span
										class="relative z-10 flex h-7 w-7 shrink-0 items-center justify-center rounded-full bg-gray-100 text-gray-500"
									>
										<svg
											xmlns="http://www.w3.org/2000/svg"
											viewBox="0 0 24 24"
											class="h-3.5 w-3.5"
											fill="none"
											stroke="currentColor"
											stroke-width="2"
											stroke-linecap="round"
											stroke-linejoin="round"
											v-html="activityIcon(item.type)"
										/>
									</span>

									<div class="min-w-0 flex-1">
										<!-- Komentar = kartu -->
										<div
											v-if="item.type === 'comment'"
											class="rounded-lg border border-gray-200"
										>
											<div
												class="flex items-center justify-between gap-2 px-3 py-2"
											>
												<div
													class="flex min-w-0 items-center gap-2 text-base"
												>
													<span
														class="flex h-6 w-6 shrink-0 items-center justify-center rounded-full bg-orange-100 text-[10px] font-semibold text-orange-700"
													>
														{{ initials(item.user) }}
													</span>
													<span class="font-medium text-gray-900">{{
														item.user
													}}</span>
													<span class="text-gray-500">commented</span>
													<span class="text-gray-400"
														>· {{ timeAgo(item.time) }}</span
													>
												</div>
												<div
													class="flex shrink-0 items-center gap-3 text-xs text-gray-400"
												>
													<button
														type="button"
														class="hover:text-gray-600"
													>
														Edit
													</button>
													<button
														type="button"
														class="hover:text-gray-600"
													>
														···
													</button>
												</div>
											</div>
											<div
												class="px-3 pb-3 pl-11 text-base text-gray-700"
												v-html="item.content"
											/>
										</div>

										<!-- Entry satu baris -->
										<p v-else class="pt-1 text-base text-gray-600">
											<span class="font-medium text-gray-900">{{
												item.user
											}}</span>
											<span v-html="item.actionHtml" />
											<span class="text-gray-400"
												>· {{ timeAgo(item.time) }}</span
											>
										</p>
									</div>
								</li>
							</ol>
						</div>

						<!-- TAB: Comments -->
						<div v-else-if="activeTab === 'comments'">
							<div class="mb-5 flex items-center justify-between">
								<h2 class="text-lg font-semibold text-gray-900">Comments</h2>
								<button
									type="button"
									class="rounded-lg bg-primary px-3 py-1.5 text-sm font-medium text-white transition hover:opacity-90"
									@click="comments.showForm = !comments.showForm"
								>
									+ New Comment
								</button>
							</div>

							<!-- Form tambah comment -->
							<div v-if="comments.showForm" class="mb-5">
								<textarea
									v-model="comments.body"
									rows="3"
									placeholder="Tulis komentar…"
									:class="[inputClass, 'resize-none']"
								/>
								<div class="mt-2 flex items-center gap-2">
									<button
										type="button"
										:disabled="comments.submitting || !comments.body.trim()"
										class="rounded-lg bg-primary px-4 py-2 text-sm font-medium text-white transition hover:opacity-90 disabled:cursor-not-allowed disabled:opacity-50"
										@click="submitComment"
									>
										{{ comments.submitting ? 'Mengirim…' : 'Kirim' }}
									</button>
									<button
										type="button"
										class="rounded-lg border border-gray-300 px-4 py-2 text-sm font-medium text-gray-700 transition hover:bg-gray-50"
										@click=";(comments.showForm = false), (comments.body = '')"
									>
										Batal
									</button>
								</div>
							</div>

							<p v-if="comments.loading" class="text-base text-gray-500">
								Loading...
							</p>
							<pre
								v-else-if="comments.error"
								class="text-base text-red-600 whitespace-pre-wrap"
								>{{ comments.error }}</pre
							>
							<p v-else-if="!comments.items.length" class="text-base text-gray-400">
								Belum ada komentar.
							</p>

							<ul v-else class="space-y-4">
								<li
									v-for="c in comments.items"
									:key="c.name"
									class="rounded-lg border border-gray-200"
								>
									<div class="flex items-center gap-2 px-3 py-2 text-base">
										<span
											class="flex h-6 w-6 shrink-0 items-center justify-center rounded-full bg-orange-100 text-[10px] font-semibold text-orange-700"
										>
											{{ initials(c.comment_by || c.owner) }}
										</span>
										<span class="font-medium text-gray-900">{{
											c.comment_by || c.owner
										}}</span>
										<span class="text-gray-500">added a comment</span>
										<span class="text-gray-400"
											>· {{ timeAgo(c.creation) }}</span
										>
									</div>
									<div
										class="px-3 pb-3 pl-11 text-sm text-gray-700"
										v-html="c.content"
									/>
								</li>
							</ul>
						</div>

						<!-- TAB: Attachments → File Kredit + Upload File Pendukung -->
						<div v-else-if="activeTab === 'attachments'" class="space-y-6">
							<!-- File Kredit (field Attach) → label & tombol Attach selalu ada -->
							<section v-if="attachFields.length">
								<div class="mb-3 flex flex-wrap items-center gap-x-2 gap-y-1">
									<h2 class="text-lg font-semibold text-gray-900">
										File Kredit
									</h2>
								</div>
								<pre
									v-if="kreditError"
									class="mb-3 text-sm text-red-600 whitespace-pre-wrap"
									>{{ kreditError }}</pre
								>
								<div class="grid grid-cols-1 gap-4 md:grid-cols-2">
									<!-- Tiap File Kredit = kartu "Documents" (gaya referensi) -->
									<div
										v-for="f in attachFields"
										:key="f.fieldname"
										class="rounded-2xl border border-gray-200 bg-white p-4"
									>
										<div class="flex items-center justify-between gap-3">
											<p
												class="min-w-0 truncate text-base font-semibold text-gray-800"
											>
												{{ f.label }}
											</p>
											<button
												type="button"
												:disabled="
													isAttachReadOnly(f) ||
													kreditUploading === f.fieldname ||
													kreditDeleting === f.fieldname
												"
												class="inline-flex shrink-0 items-center gap-1.5 rounded-full border border-primary px-3.5 py-2 text-xs font-semibold text-primary transition hover:bg-primary/5 disabled:cursor-not-allowed disabled:opacity-50"
												@click="triggerKreditPick(f)"
											>
												<svg
													xmlns="http://www.w3.org/2000/svg"
													viewBox="0 0 24 24"
													class="h-4 w-4 shrink-0"
													fill="none"
													stroke="currentColor"
													stroke-width="2"
													stroke-linecap="round"
													stroke-linejoin="round"
												>
													<circle cx="12" cy="12" r="10" />
													<path d="m16 12-4-4-4 4" />
													<path d="M12 16V8" />
												</svg>
												Upload Files
											</button>
										</div>
										<p class="mt-2 text-xs text-gray-400">
											Wajib PDF · maks {{ MAX_FILE_MB }} MB
										</p>

										<!-- File sudah ada → chip nama file + tombol hapus -->
										<div
											v-if="form[f.fieldname]"
											class="mt-3 flex items-center justify-between gap-2 rounded-lg border border-gray-200 bg-gray-50 px-3 py-2"
										>
											<a
												:href="form[f.fieldname]"
												target="_blank"
												rel="noopener"
												class="min-w-0 truncate text-base font-medium text-primary hover:underline"
												@click.prevent="
													openAttachment(
														form[f.fieldname],
														fileName(form[f.fieldname])
													)
												"
											>
												{{ fileName(form[f.fieldname]) }}
											</a>
											<button
												v-if="!isAttachReadOnly(f)"
												type="button"
												:disabled="
													kreditUploading === f.fieldname ||
													kreditDeleting === f.fieldname
												"
												class="flex h-7 w-7 shrink-0 items-center justify-center rounded-md text-red-500 transition hover:bg-red-50 hover:text-red-600 disabled:cursor-not-allowed disabled:opacity-50"
												title="Hapus file"
												@click="deleteKreditFile(f)"
											>
												<svg
													xmlns="http://www.w3.org/2000/svg"
													viewBox="0 0 24 24"
													class="h-4 w-4"
													fill="none"
													stroke="currentColor"
													stroke-width="2"
													stroke-linecap="round"
													stroke-linejoin="round"
												>
													<path d="M3 6h18" />
													<path
														d="M19 6v14a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V6m3 0V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2"
													/>
													<line x1="10" y1="11" x2="10" y2="17" />
													<line x1="14" y1="11" x2="14" y2="17" />
												</svg>
											</button>
										</div>

										<span
											v-if="
												kreditUploading === f.fieldname ||
												kreditDeleting === f.fieldname
											"
											class="mt-2 block text-xs text-gray-400"
										>
											{{
												kreditUploading === f.fieldname
													? 'Mengupload…'
													: 'Menghapus…'
											}}
										</span>
									</div>
								</div>
								<!-- Satu input file tersembunyi, dipakai bergantian antar field.
							     Hanya PDF (lihat validateFile di onKreditFileChange). -->
								<input
									ref="kreditInput"
									type="file"
									accept="application/pdf,.pdf"
									class="hidden"
									@change="onKreditFileChange"
								/>
							</section>

							<!-- Upload File Pendukung (child table table_otkl) → tabel selalu tampil -->
							<section>
								<div class="mb-3 flex flex-wrap items-center gap-x-2 gap-y-1">
									<h2 class="text-lg font-semibold text-gray-900">
										Upload File Pendukung
									</h2>
									<span class="text-xs font-medium text-gray-400">
										JPG, PNG, atau PDF · maks {{ MAX_FILE_MB }} MB
									</span>
								</div>
								<pre
									v-if="pendukung.error"
									class="mb-3 text-sm text-red-600 whitespace-pre-wrap"
									>{{ pendukung.error }}</pre
								>

								<div class="overflow-x-auto rounded-lg border border-gray-200">
									<table class="w-full min-w-[480px] text-base">
										<thead>
											<tr
												class="border-b border-gray-200 bg-gray-100 text-left"
											>
												<th class="px-4 py-2 font-medium text-gray-500">
													Nama File
												</th>
												<th class="px-4 py-2 font-medium text-gray-500">
													File
												</th>
												<th class="px-4 py-2 font-medium text-gray-500">
													Aksi
												</th>
											</tr>
										</thead>
										<tbody class="divide-y divide-gray-100">
											<!-- Baris existing / staged -->
											<tr
												v-for="(row, idx) in attachmentRows"
												:key="row.name || `new-${idx}`"
											>
												<td class="px-4 py-2 align-top text-gray-800">
													{{ row.nama_file || '—' }}
												</td>
												<td class="px-4 py-2 align-top">
													<a
														v-if="row.upload_file_pdf_png_jpg"
														:href="row.upload_file_pdf_png_jpg"
														target="_blank"
														rel="noopener"
														class="font-medium text-primary hover:underline"
														@click.prevent="
															openAttachment(
																row.upload_file_pdf_png_jpg,
																fileName(
																	row.upload_file_pdf_png_jpg
																)
															)
														"
													>
														{{ fileName(row.upload_file_pdf_png_jpg) }}
													</a>
													<span v-else class="text-gray-400">—</span>
												</td>
												<td class="px-4 py-2 align-top">
													<button
														v-if="pendukungEditable"
														type="button"
														class="flex h-8 w-8 items-center justify-center rounded-md text-red-500 transition hover:bg-red-50 hover:text-red-600"
														title="Hapus baris"
														@click="removePendukungRow(idx, row)"
													>
														<svg
															xmlns="http://www.w3.org/2000/svg"
															viewBox="0 0 24 24"
															class="h-4 w-4"
															fill="none"
															stroke="currentColor"
															stroke-width="2"
															stroke-linecap="round"
															stroke-linejoin="round"
														>
															<path d="M3 6h18" />
															<path
																d="M19 6v14a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2V6m3 0V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2"
															/>
															<line
																x1="10"
																y1="11"
																x2="10"
																y2="17"
															/>
															<line
																x1="14"
																y1="11"
																x2="14"
																y2="17"
															/>
														</svg>
													</button>
												</td>
											</tr>

											<!-- Baris tambah → hanya saat bisa diedit (status Draft & mode edit) -->
											<tr v-if="pendukungEditable" class="bg-gray-50">
												<!-- Nama File → dropdown custom (panel di-teleport, anti-clip) -->
												<td class="px-4 py-2 align-top">
													<SelectMenu
														v-model="pendukung.namaFile"
														:options="pendukungOptions"
														placeholder="Pilih nama file…"
														:btn-class="inputClass"
													/>
												</td>
												<!-- Pilih file → LANGSUNG upload (tanpa tombol Tambah) -->
												<td class="px-4 py-2 align-top" colspan="2">
													<div class="flex items-center gap-2">
														<button
															type="button"
															:disabled="
																!pendukung.namaFile ||
																pendukung.submitting
															"
															class="inline-flex min-h-[44px] shrink-0 items-center gap-1.5 rounded-md border border-gray-300 bg-white px-3 py-2 text-sm font-medium text-gray-700 transition hover:bg-gray-50 disabled:cursor-not-allowed disabled:opacity-50 md:min-h-0"
															@click="triggerPendukungPick"
														>
															<svg
																v-if="!pendukung.submitting"
																xmlns="http://www.w3.org/2000/svg"
																viewBox="0 0 24 24"
																class="h-4 w-4 shrink-0 text-gray-400"
																fill="none"
																stroke="currentColor"
																stroke-width="2"
																stroke-linecap="round"
																stroke-linejoin="round"
															>
																<path
																	d="m21.44 11.05-9.19 9.19a6 6 0 0 1-8.49-8.49l8.57-8.57A4 4 0 1 1 18 8.84l-8.59 8.57a2 2 0 0 1-2.83-2.83l8.49-8.48"
																/>
															</svg>
															<svg
																v-else
																xmlns="http://www.w3.org/2000/svg"
																viewBox="0 0 24 24"
																class="h-4 w-4 shrink-0 animate-spin text-gray-400"
																fill="none"
																stroke="currentColor"
																stroke-width="2"
																stroke-linecap="round"
																stroke-linejoin="round"
															>
																<path
																	d="M21 12a9 9 0 1 1-6.219-8.56"
																/>
															</svg>
															{{
																pendukung.submitting
																	? 'Mengupload…'
																	: 'Pilih File'
															}}
														</button>
														<span
															class="min-w-0 flex-1 truncate text-xs text-gray-500"
														>
															{{
																pendukung.namaFile
																	? 'File langsung terupload saat dipilih'
																	: 'Pilih Nama File dulu'
															}}
														</span>
													</div>
													<!-- Auto-upload saat file dipilih. -->
													<input
														ref="pendukungInput"
														type="file"
														accept=".jpg,.jpeg,.png,.pdf,image/jpeg,image/png,application/pdf"
														class="hidden"
														@change="onPendukungFileChange"
													/>
												</td>
											</tr>
										</tbody>
									</table>
								</div>
							</section>
						</div>
					</div>
				</div>
			</div>
		</div>

		<!-- ====== Bottom bar: Save (mode edit) atau Actions (mode baca) ====== -->
		<Transition
			enter-active-class="transition duration-200 ease-out"
			enter-from-class="translate-y-2 opacity-0"
			leave-active-class="transition duration-150 ease-in"
			leave-to-class="translate-y-2 opacity-0"
		>
			<div
				v-if="
					doc.data &&
					(editMode || transitions.items.length || showFormHasil || showDiskresi)
				"
				class="sticky bottom-0 z-20 border-t border-gray-200 bg-white px-4 py-3 md:px-6"
			>
				<!-- Mode edit → tombol Save (full-width, biru) -->
				<button
					v-if="editMode"
					type="button"
					:disabled="saving"
					class="flex w-full items-center justify-center gap-2 rounded-full bg-primary py-3 text-sm font-semibold text-white shadow-sm transition active:scale-[0.99] disabled:cursor-not-allowed disabled:opacity-50"
					@click="saveDocument"
				>
					<svg
						v-if="saving"
						xmlns="http://www.w3.org/2000/svg"
						viewBox="0 0 24 24"
						class="h-4 w-4 animate-spin"
						fill="none"
						stroke="currentColor"
						stroke-width="2"
						stroke-linecap="round"
						stroke-linejoin="round"
					>
						<path d="M21 12a9 9 0 1 1-6.219-8.56" />
					</svg>
					{{ saving ? 'Menyimpan…' : 'Save' }}
				</button>
				<!-- Mode baca → Form Hasil (cetak PDF) + Actions (transisi workflow).
				     Tampil berdampingan bila keduanya tersedia; sendiri = full-width. -->
				<div v-else class="flex items-center gap-2">
					<!-- Form Hasil → pilih Download PDF Internal / Eksternal -->
					<button
						v-if="showFormHasil"
						type="button"
						class="flex flex-1 items-center justify-center gap-2 rounded-full border border-primary bg-white py-3 text-sm font-semibold text-primary shadow-sm transition hover:bg-primary/5 active:scale-[0.99]"
						@click="formHasilOpen = true"
					>
						<svg
							xmlns="http://www.w3.org/2000/svg"
							viewBox="0 0 24 24"
							class="h-4 w-4"
							fill="none"
							stroke="currentColor"
							stroke-width="2"
							stroke-linecap="round"
							stroke-linejoin="round"
						>
							<path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z" />
							<path d="M14 2v6h6" />
							<path d="M16 13H8" />
							<path d="M16 17H8" />
							<path d="M10 9H8" />
						</svg>
						Form Hasil
					</button>
					<!-- Diskresi → hanya status CA Approved / Banding Approved -->
					<button
						v-if="showDiskresi"
						type="button"
						class="flex flex-1 items-center justify-center gap-2 rounded-full border border-primary bg-white py-3 text-sm font-semibold text-primary shadow-sm transition hover:bg-primary/5 active:scale-[0.99]"
						@click="openDiskresiCreate"
					>
						<svg
							xmlns="http://www.w3.org/2000/svg"
							viewBox="0 0 24 24"
							class="h-4 w-4"
							fill="none"
							stroke="currentColor"
							stroke-width="2"
							stroke-linecap="round"
							stroke-linejoin="round"
						>
							<path d="M12 20h9" />
							<path d="M16.5 3.5a2.121 2.121 0 0 1 3 3L7 19l-4 1 1-4 12.5-12.5z" />
						</svg>
						Diskresi
					</button>
					<!-- Actions → transisi workflow (hanya bila ada aksi untuk user) -->
					<button
						v-if="transitions.items.length"
						type="button"
						class="flex flex-1 items-center justify-center gap-2 rounded-full bg-primary py-3 text-sm font-semibold text-white shadow-sm transition active:scale-[0.99]"
						@click="actionsOpen = true"
					>
						<svg
							xmlns="http://www.w3.org/2000/svg"
							viewBox="0 0 24 24"
							class="h-4 w-4"
							fill="none"
							stroke="currentColor"
							stroke-width="2"
							stroke-linecap="round"
							stroke-linejoin="round"
						>
							<circle cx="12" cy="12" r="1" />
							<circle cx="19" cy="12" r="1" />
							<circle cx="5" cy="12" r="1" />
						</svg>
						Actions
					</button>
				</div>
			</div>
		</Transition>

		<!-- ====== Bottom-sheet daftar Actions (animasi naik) ====== -->
		<Teleport to="body">
			<Transition
				enter-active-class="transition-opacity duration-200"
				enter-from-class="opacity-0"
				leave-active-class="transition-opacity duration-150"
				leave-to-class="opacity-0"
			>
				<div
					v-if="actionsOpen"
					class="fixed inset-0 z-[70] flex items-end justify-center bg-black/40"
					@click.self="actionsOpen = false"
				>
					<Transition
						appear
						enter-active-class="transition-transform duration-200 ease-out"
						enter-from-class="translate-y-full"
						leave-active-class="transition-transform duration-150 ease-in"
						leave-to-class="translate-y-full"
					>
						<div
							v-if="actionsOpen"
							class="w-full max-w-screen-sm rounded-t-3xl bg-white px-5 pb-[max(1.25rem,env(safe-area-inset-bottom))] pt-3 text-xs shadow-2xl"
						>
							<div class="mx-auto mb-4 h-1.5 w-10 rounded-full bg-gray-300" />
							<h2 class="mb-4 text-center text-base font-semibold text-gray-900">
								Actions
							</h2>

							<p
								v-if="transitions.loading"
								class="py-3 text-center text-sm text-gray-400"
							>
								Memuat aksi…
							</p>
							<p
								v-else-if="!transitions.items.length"
								class="py-3 text-center text-sm text-gray-400"
							>
								Tidak ada aksi tersedia untuk Anda.
							</p>
							<div v-else class="max-h-[55vh] space-y-2 overflow-y-auto px-0.5">
								<button
									v-for="t in transitions.items"
									:key="t.action"
									type="button"
									:disabled="!!transitions.applying"
									class="flex w-full items-center justify-between gap-2 rounded-2xl border border-gray-200 px-4 py-3.5 text-left transition hover:border-primary hover:bg-primary/5 disabled:opacity-50"
									@click="onActionClick(t.action)"
								>
									<span class="text-sm font-semibold text-gray-800">{{
										t.action
									}}</span>
									<span class="shrink-0 text-xs text-gray-400"
										>→ {{ t.next_state }}</span
									>
								</button>
							</div>
							<p
								v-if="transitions.applying"
								class="mt-3 text-center text-xs text-gray-400"
							>
								Menerapkan “{{ transitions.applying }}”…
							</p>
						</div>
					</Transition>
				</div>
			</Transition>
		</Teleport>

		<!-- ====== Bottom-sheet input aksi banding (alasan / PIC / keterangan) ====== -->
		<Teleport to="body">
			<Transition
				enter-active-class="transition-opacity duration-200"
