	return true
}

// ---- Mode baca/edit --------------------------------------------------------
// Detail bersifat READ-ONLY secara default (semua field terkunci). Boleh diedit
// mengikuti workflow "Flow Kredit" — PERSIS aturan desk (frappe.workflow.is_read_only):
// dokumen ber-workflow editable HANYA bila user punya salah satu role `allow_edit`
// pada state saat ini (mis. Draft→CMO, Proses CA→Credit Analyst, Proses Banding→
// Pembanding/CMO). Editabilitas per-field tetap disaring permlevel & read_only_depends_on.
const editMode = ref(false)

// Peta state → role allow_edit dari workflow (diambil server-side agar sinkron).
const wfStateField = ref(null)
const wfEditStates = ref({})
const wfLoaded = ref(false)
async function loadWorkflowEditMap() {
	try {
		const params = new URLSearchParams({ doctype: 'Data Pengajuan' })
		const res = await fetch(
			`/api/method/juragan.api.portal.meta.get_workflow_edit_map?${params.toString()}`,
			{ method: 'GET', credentials: 'include', headers: { Accept: 'application/json' } }
		)
		if (res.ok) {
			const msg = (await res.json()).message || {}
			wfStateField.value = msg.state_field || null
			wfEditStates.value = msg.states || {}
		}
	} catch (e) {
		/* fallback: tanpa data workflow → anggap tak boleh edit (aman) */
	} finally {
		wfLoaded.value = true
	}
}

// Boleh edit dokumen? Mirror PERSIS frappe.workflow.is_read_only (dibalik):
//  - belum tahu (map/role belum dimuat) → false (aman, kunci dulu)
//  - tak ada workflow (state_field null) → true
//  - status kosong → true
//  - selain itu → user punya salah satu role allow_edit pada status ini
// Tidak ada lagi pengecualian banding hardcode: editabilitas mengikuti allow_edit
// workflow apa adanya (mis. CA Rejected & Proses Banding = CMO; Banding Rejected =
// Administrator saja) supaya sama dengan desk.
const canEditDoc = computed(() => {
	if (!wfLoaded.value || !currentUser.rolesLoaded) return false
	if (!wfStateField.value) return true
	const status = doc.data?.status
	if (!status) return true
	const mine = currentUser.roles || []
	const allow = wfEditStates.value[status] || []
	return allow.some((r) => mine.includes(r))
})

function enterEditMode() {
	if (canEditDoc.value) editMode.value = true
}
// Begitu dokumen jadi tak-boleh-edit (mis. pindah state) → kunci lagi & matikan editMode.
watch(canEditDoc, (can) => {
	if (!can) editMode.value = false
})

// ---- Sub-tab tab "Data" = Tab Break, DI-RENDER DARI META DOCTYPE -----------
// Field, urutan (idx), tipe, & options diambil dari meta (getdoctype) supaya
// PERSIS mengikuti definisi Frappe — bukan hardcode yang bisa drift/acak.
const activeSubtab = ref('')
const metaFields = ref([])
const metaError = ref('')

// Nilai field yang bisa diedit (copy dari dokumen saat load).
const form = reactive({})

// ---- Status "dirty" untuk tombol Save -------------------------------------
// dirty = ada perubahan belum disimpan (edit field / upload / tambah-hapus file).
// applyingRemote = true saat kita mengisi form dari server (load/save/workflow) →
// supaya perubahan terprogram itu TIDAK ikut menandai dirty.
const dirty = ref(false)
const applyingRemote = ref(false)
const saving = ref(false)
const saveError = ref('')

watch(
	form,
	() => {
		if (!applyingRemote.value) dirty.value = true
	},
	{ deep: true }
)

// Sinkronkan form dari dokumen server tanpa memicu dirty.
async function syncFormFromDoc() {
	applyingRemote.value = true
	try {
		Object.assign(form, doc.data || {})
		// Samakan tipe nilai Link → string (cocok dgn value <option> dropdown).
		for (const f of metaFields.value) {
			if (f.fieldtype === 'Link' && form[f.fieldname] != null && form[f.fieldname] !== '') {
				form[f.fieldname] = String(form[f.fieldname])
			}
		}
		await nextTick()
	} finally {
		applyingRemote.value = false
	}
	dirty.value = false
}

// Kelas input form editable (dipakai semua widget). Isi field = 12px (text-xs).
// Catatan: di bawah 16px, iOS akan zoom saat input difokus — diterima sesuai
// permintaan agar seluruh teks Data Pengajuan konsisten 12px.
const inputClass =
	'min-h-[44px] w-full rounded-md border border-gray-300 bg-white px-3 py-2 text-base text-gray-800 outline-none transition focus:border-primary focus:ring-2 focus:ring-inset focus:ring-primary/30 md:min-h-0'

// Permlevel yang boleh DIBACA / DITULIS user (dari docperm × roles user). permlevel 0
// selalu boleh baca (user sudah bisa membuka dokumen ini). Meniru frappe.perm: field di
// permlevel tanpa hak baca → disembunyikan; punya baca tapi tanpa tulis → read-only.
// Permlevel yang boleh DIBACA / DITULIS user — SUMBER KEBENARAN = Frappe
// (Meta.get_permlevel_access via endpoint portal). JANGAN dihitung dari DocPerm
// mentah: akses Data Pengajuan untuk CMO datang lewat has_permission hook (bukan
// DocPerm), sehingga perhitungan manual keliru menyembunyikan field permlevel>0
// dan membuat tab pertama tampak kosong ("Memuat field…").
const readablePermlevels = ref(new Set([0]))
const writablePermlevels = ref(new Set([0]))

async function loadPermlevelAccess() {
	try {
		const params = new URLSearchParams({ doctype: 'Data Pengajuan' })
		const res = await fetch(
			`/api/method/juragan.api.portal.meta.get_permlevel_access?${params.toString()}`,
			{ method: 'GET', credentials: 'include', headers: { Accept: 'application/json' } }
		)
		if (!res.ok) return
		const json = await res.json()
		const msg = json.message || {}
		if (Array.isArray(msg.read)) readablePermlevels.value = new Set([0, ...msg.read])
		if (Array.isArray(msg.write)) writablePermlevels.value = new Set([0, ...msg.write])
	} catch (e) {
		/* fallback: hanya permlevel 0 */
	}
}
function canReadPermlevel(f) {
	return readablePermlevels.value.has(f.permlevel || 0)
}

// Field "Informasi Hasil" yang hanya relevan setelah ada hasil → sembunyikan
// selama nilainya kosong atau masih nilai default (mis. cnkkp = "Belum / Tidak
// ada data ditemukan"). Berlaku reaktif karena membaca `form`.
const HIDE_IF_EMPTY = new Set([
	'no_perjanjian',
	'tanggal_pencairan',
	'tanggal_hasil', // Tanggal Hasil CA
	'keputusan_credit_analyst',
	'cnkkp', // Hasil Cek NIK & No KK Internal
	'keterangan_cancel_approval',
])
function isEmptyOrDefault(f) {
	const v = form[f.fieldname]
	const empty = v == null || (typeof v === 'string' ? v.trim() === '' : v === '')
	if (empty) return true
	const def = f.default
	return def != null && def !== '' && String(v).trim() === String(def).trim()
}
// Nilai field kosong/null (0 & false TIDAK dianggap kosong).
function isFieldNull(f) {
	const v = form[f.fieldname]
	return v == null || (typeof v === 'string' ? v.trim() === '' : v === '')
}

// Susun tab → section → kolom → field dari meta (urut sesuai idx asli).
const dataTabs = computed(() => {
	const tabs = []
	let curTab = null
	let curSection = null
	let curCol = null
	for (const f of metaFields.value) {
		const ft = f.fieldtype
		if (ft === 'Tab Break') {
			curTab = { key: f.fieldname, label: f.label || f.fieldname, sections: [] }
			tabs.push(curTab)
			curSection = null
			curCol = null
			continue
		}
		if (!curTab) continue
		if (ft === 'Section Break') {
			curCol = []
			curSection = {
				label: f.label || '',
				depends_on: f.depends_on,
				columns: [curCol],
			}
			curTab.sections.push(curSection)
			continue
		}
		if (ft === 'Column Break') {
			if (!curSection) {
				curCol = []
				curSection = { label: '', columns: [curCol] }
				curTab.sections.push(curSection)
			} else {
				curCol = []
				curSection.columns.push(curCol)
			}
			continue
		}
		// Lewati field non-input & yang disembunyikan.
		if (
			[
				'HTML',
				'Button',
				'Heading',
				'Fold',
				'Image',
				'Barcode',
				'Table',
				'Table MultiSelect',
				'Attach',
				'Attach Image', // → dipindah ke tab Attachments
			].includes(ft)
		)
			continue
		if (f.hidden) continue
		// permlevel tanpa hak baca → sembunyikan (persis form Frappe).
		if (!canReadPermlevel(f)) continue
		// Field hasil tertentu → sembunyikan kalau nilainya kosong / masih default.
		if (HIDE_IF_EMPTY.has(f.fieldname) && isEmptyOrDefault(f)) continue
		// Field read-only yang KOSONG (null) → sembunyikan (perilaku Frappe: read-only
		// tanpa isi tidak ditampilkan). Termasuk read-only via read_only_depends_on
		// (mis. `kategori_enduser` yang terkunci selama status bukan "Proses CA") — jadi
		// tidak muncul sebagai "—" saat masih kosong. Begitu field jadi editable (status
		// Proses CA + role berhak), kondisi read-only bernilai false → tetap tampil.
		if (fieldLevelReadOnly(f) && isFieldNull(f)) continue
		// depends_on Frappe → sembunyikan kalau kondisinya tidak terpenuhi.
		if (f.depends_on && !evalCondition(f.depends_on)) continue
		if (!curSection) {
			curCol = []
			curSection = { label: '', columns: [curCol] }
			curTab.sections.push(curSection)
		}
		curCol.push(f)
	}
	// Buang kolom kosong (mis. Column Break tepat setelah Section Break bikin
	// kolom kosong di kiri), lalu buang section yang tak punya field sama sekali.
	for (const t of tabs) {
		t.sections = t.sections
			// Section Break depends_on → sembunyikan seluruh section by status.
			.filter((s) => evalCondition(s.depends_on))
			.map((s) => ({ ...s, columns: s.columns.filter((c) => c.length) }))
			.filter((s) => s.columns.length)
	}
	return tabs
})

const SUBTABS = computed(() => dataTabs.value.map((t) => ({ key: t.key, label: t.label })))

// Inisialisasi sub-tab aktif SEKALI → default ke sub-tab PERTAMA ("Data Nasabah").
// PENTING: jangan inisialisasi sebelum permlevel access + form selesai dimuat
// (`coreLoaded`). Kalau tidak, saat awal banyak field permlevel>0 / depends_on masih
// tersembunyi sehingga "Data Nasabah" tampak kosong dan pilihan keliru terkunci ke
// tab non-kosong pertama yang kebetulan terlihat (mis. "Informasi Hasil").
const subtabInitialized = ref(false)
const coreLoaded = ref(false)
function initActiveSubtab() {
	if (subtabInitialized.value || !coreLoaded.value) return
	const tabs = dataTabs.value
	if (!tabs.length) return
	// Utamakan sub-tab pertama (Data Nasabah); kalau kebetulan kosong untuk user ini,
	// jatuh ke sub-tab non-kosong pertama.
	const pick = tabs[0].sections.length ? tabs[0] : tabs.find((t) => t.sections.length)
	if (pick) {
		activeSubtab.value = pick.key
		subtabInitialized.value = true
	}
}
// Safety net: kalau dataTabs masih berubah setelah load (mis. resolusi link/async),
// tetap inisialisasi begitu siap. Gated oleh coreLoaded supaya tak terkunci dini.
watch(dataTabs, () => initActiveSubtab())

// ---- Offset sticky (DIUKUR dinamis) ---------------------------------------
// Header, tab utama, & sub-tab semuanya sticky. Supaya tidak ada celah/tumpang-
// tindih, posisi `top` tab & sub-tab dihitung dari tinggi elemen di atasnya
// (bukan angka hardcode yang bisa meleset saat tinggi berubah / status panjang).
const headerRef = ref(null)
const tabStripRef = ref(null)
const tabTop = ref(0) // sticky tab utama = tinggi header
const subTop = ref(0) // sticky sub-tab = tinggi header + tab utama
function measureSticky() {
	const h = headerRef.value?.offsetHeight || 0
	const t = tabStripRef.value?.offsetHeight || 0
	// Overlap 1px tiap bar → tidak ada celah rambut akibat pembulatan sub-pixel.
	// Bar dgn z lebih tinggi (header > tab > sub-tab) tetap menutupi, jadi garis
	// pemisahnya tetap kelihatan.
	tabTop.value = Math.max(0, h - 1)
	subTop.value = Math.max(0, tabTop.value + t - 1)
}
let _stickyRO = null
function setupStickyObservers() {
	if (typeof ResizeObserver === 'undefined') return
	_stickyRO = new ResizeObserver(() => measureSticky())
	if (headerRef.value) _stickyRO.observe(headerRef.value)
	if (tabStripRef.value) _stickyRO.observe(tabStripRef.value)
}
// Re-ukur saat ganti tab (tinggi tab strip konsisten, tapi sub-tab muncul/hilang).
watch(activeTab, () => nextTick(measureSticky))
onMounted(() => window.addEventListener('resize', measureSticky))
onBeforeUnmount(() => {
	_stickyRO?.disconnect()
	window.removeEventListener('resize', measureSticky)
})

// Baris child table "Upload File Pendukung" (table_otkl) → dari form (termasuk baris
// yang baru ditambahkan & belum disimpan), bukan doc.data.
const attachmentRows = computed(() => form.table_otkl || [])

// Field Attach (File Kredit: File 1/2/3) → dipindah ke tab Attachments.
const attachFields = computed(() =>
	metaFields.value.filter(
		(f) => ['Attach', 'Attach Image'].includes(f.fieldtype) && !f.hidden && canReadPermlevel(f)
	)
)

// Child table "Upload File Pendukung" (table_otkl) hanya bisa diubah (tambah/hapus
// baris, upload) saat field-nya editable — yaitu mode edit & dokumen boleh diedit
// di status ini (aturan workflow), serta tidak read-only by permlevel /
// read_only_depends_on. Fallback: kalau meta belum ada, ikut editMode + canEditDoc.
const pendukungField = computed(() => metaFields.value.find((f) => f.fieldname === 'table_otkl'))
const pendukungEditable = computed(() => {
	const f = pendukungField.value
	if (!f) return editMode.value && canEditDoc.value
	return !isFieldReadOnly(f)
})

// Helper widget per fieldtype.
function selectOptions(field) {
	return String(field.options || '')
		.split('\n')
		.map((s) => s.trim())
		.filter(Boolean)
}
function isTextarea(ft) {
	return ['Small Text', 'Text', 'Long Text', 'Code', 'Text Editor'].includes(ft)
}
function isNumberField(ft) {
	return ['Int', 'Float', 'Currency', 'Percent'].includes(ft)
}

// Evaluasi ekspresi kondisi Frappe (depends_on / mandatory_depends_on) thd dokumen.
// Mengakses `form` reaktif → ikut ter-track, jadi show/hide otomatis update.
function evalCondition(expr) {
	if (!expr) return true
	try {
		const code = String(expr).replace(/^eval:/, '')
		// Helper Frappe yang sering dipakai di ekspresi eval.
		const in_list = (list, item) => Array.isArray(list) && list.includes(item)
		const cint = (v) => parseInt(v, 10) || 0
		const cstr = (v) => (v == null ? '' : String(v))
		const flt = (v) => parseFloat(v) || 0
		// Shim `frappe.session.user` supaya depends_on seperti
		// `frappe.session.user === "Administrator"` (mis. Status Geocoding) benar-benar
		// dievaluasi, bukan gagal → fail-open (dulu bikin field admin-only tetap tampil).
		const frappe = { session: { user: currentUser.user } }
		// eslint-disable-next-line no-new-func
		return !!new Function(
			'doc',
			'in_list',
			'cint',
			'cstr',
			'flt',
			'frappe',
			`return (${code})`
		)(form, in_list, cint, cstr, flt, frappe)
	} catch (e) {
		return true // gagal evaluasi → tampilkan saja (fail-open)
	}
}
// Field wajib: reqd statis ATAU mandatory_depends_on terpenuhi.
function isFieldReqd(field) {
	if (field.reqd) return true
	return field.mandatory_depends_on ? evalCondition(field.mandatory_depends_on) : false
}

// Read-only murni field-level (tanpa gate editMode), PERSIS desk:
//  1. Tak punya hak tulis permlevel → read-only (menang atas segalanya).
//  2. `read_only_depends_on` ADA → hasilnya menentukan (MENIMPA read_only statis,
//     sama seperti set_dependant_property Frappe: prop read_only = hasil eval).
//     Mis. provinsi_domisili (read_only=1 + dep CA Rejected/Banding) → editable saat
//     Draft, terkunci saat CA Rejected.
//  3. Selain itu → ikut read_only statis.
function fieldLevelReadOnly(field) {
	if (!writablePermlevels.value.has(field.permlevel || 0)) return true
	if (field.read_only_depends_on) return evalCondition(field.read_only_depends_on)
	return !!field.read_only
}
// Field read-only di UI: mode baca selalu read-only; mode edit → aturan field-level.
function isFieldReadOnly(field) {
	if (!editMode.value) return true
	return fieldLevelReadOnly(field)
}

// Kelas input + gaya read-only (abu-abu jelas biar bisa dibedakan). Pakai modifier
// `!` (important) supaya warna read-only menang atas bg/text bawaan inputClass.
function fieldClass(field) {
	return [
		inputClass,
		isFieldReadOnly(field)
			? '!bg-gray-100 !text-gray-500 !border-gray-200 cursor-not-allowed'
			: '',
	]
}

// Format currency gaya Indonesia: 2000000 → 2.000.000,00
function formatCurrency(v) {
	const n = Number(v)
	if (v === '' || v == null || Number.isNaN(n)) return String(v ?? '')
	return new Intl.NumberFormat('id-ID', {
		minimumFractionDigits: 2,
		maximumFractionDigits: 2,
	}).format(n)
}

// Nama file dari URL Attach (segmen terakhir path).
function fileName(url) {
	if (!url) return ''
	const clean = String(url).split('?')[0]
	return decodeURIComponent(clean.substring(clean.lastIndexOf('/') + 1)) || clean
}

// Tampilan currency di dalam field: "Rp 2.500.000,00" (kosong kalau tak ada nilai).
function currencyDisplay(v) {
	if (v === '' || v == null || Number.isNaN(Number(v))) return ''
	return `Rp ${formatCurrency(v)}`
}

// Tampilan Date untuk mode baca: ISO (2026-06-15) → DD-MM-YYYY. Parse manual (bukan
// new Date) supaya bebas pergeseran timezone.
function formatDateDisplay(v) {
	if (!v) return ''
	const m = String(v).match(/^(\d{4})-(\d{2})-(\d{2})/)
	return m ? `${m[3]}-${m[2]}-${m[1]}` : String(v)
}

// Parse input currency ("Rp 2.500.000,00" / "2500000") → angka mentah.
function parseCurrency(str) {
	if (str == null) return ''
	const cleaned = String(str)
		.replace(/\./g, '') // buang titik ribuan
		.replace(',', '.') // koma desimal → titik
		.replace(/[^\d.]/g, '') // sisakan digit & titik
	if (cleaned === '') return ''
	const n = Number(cleaned)
	return Number.isNaN(n) ? '' : n
}

// Saat blur: simpan angka mentah ke form, lalu tampilkan terformat lagi.
function onCurrencyBlur(field, e) {
	const n = parseCurrency(e.target.value)
	form[field.fieldname] = n
	e.target.value = currencyDisplay(n)
}

// ---- Resolusi judul field Link (tampilkan title_field, bukan kode/name) ----
const linkTitleField = reactive({}) // { 'Data Kab Kota': 'nama_kab_kota', ... }
const linkTitles = reactive({}) // { 'Data Kab Kota:21.71': 'KOTA BATAM' }
const linkOptions = reactive({}) // { 'Data Penghasilan': [{value,label}], ... } (≤100 record)

// Cache judul Link di localStorage → tampil INSTAN utk kode yang pernah dilihat
// (master data spt kelurahan/kecamatan/kota jarang berubah). Preload saat setup.
const LINK_TITLE_CACHE_KEY = 'dp-link-titles'
try {
	const raw = localStorage.getItem(LINK_TITLE_CACHE_KEY)
	if (raw) Object.assign(linkTitles, JSON.parse(raw))
} catch (e) {
	/* ignore */
}
function saveLinkTitle(key, title) {
	linkTitles[key] = title
	try {
		const raw = localStorage.getItem(LINK_TITLE_CACHE_KEY)
		const map = raw ? JSON.parse(raw) : {}
		map[key] = title
		localStorage.setItem(LINK_TITLE_CACHE_KEY, JSON.stringify(map))
	} catch (e) {
		/* ignore (mis. storage penuh / private mode) */
	}
}

// Ambil title_field tiap doctype tujuan Link, lalu resolve judul nilai dokumen.
// FASE 1 (cepat, getdoctype) → resolve judul → FASE 2 (preload opsi, background).
async function loadLinkMeta() {
	const dts = new Set()
	for (const f of metaFields.value) {
		if (f.fieldtype === 'Link' && f.options) dts.add(f.options)
	}
	// Fase 1: title_field tiap doctype (cepat).
	await Promise.all(
		[...dts].map(async (dt) => {
			try {
				const res = await fetch(
					`/api/method/frappe.desk.form.load.getdoctype?doctype=${encodeURIComponent(
						dt
					)}`,
					{
						method: 'GET',
						credentials: 'include',
						headers: { Accept: 'application/json' },
					}
				)
				const json = await res.json()
				const docs = json.docs || json.message?.docs || []
				const meta = docs.find((x) => x.name === dt) || docs[0]
				linkTitleField[dt] = (meta && meta.title_field) || null
			} catch (e) {
				linkTitleField[dt] = null
			}
		})
	)
	// Judul nilai dokumen sekarang → muncul cepat (hanya get_value per field).
	resolveAllLinks()
	// Fase 2: preload opsi dropdown (≤100) di background — untuk UX dropdown saja.
	for (const dt of dts) loadLinkOptions(dt)
}

// Preload opsi dropdown (≤100 record) untuk satu doctype tujuan Link.
async function loadLinkOptions(dt) {
	if (linkOptions[dt]) return
	const titleField = linkTitleField[dt]
	try {
		const flds = titleField ? ['name', titleField] : ['name']
		const lparams = new URLSearchParams({
			doctype: dt,
			fields: JSON.stringify(flds),
			limit_page_length: '101',
			order_by: 'name asc',
		})
		const lres = await fetch(`/api/method/frappe.client.get_list?${lparams.toString()}`, {
			method: 'GET',
			credentials: 'include',
			headers: { Accept: 'application/json' },
		})
		const ljson = await lres.json()
		const recs = ljson.message || []
		if (recs.length && recs.length <= 100) {
			linkOptions[dt] = recs.map((r) => ({
				value: String(r.name),
				label: (titleField && r[titleField]) || String(r.name),
			}))
		}
	} catch (e) {
		// abaikan → fallback ke resolusi judul / read-only
	}
}

// Resolusi satu nilai link → simpan ke linkTitles (reaktif).
async function resolveLinkTitle(dt, value) {
	const key = `${dt}:${value}`
	if (value == null || value === '' || linkTitles[key] !== undefined) return
	const titleField = linkTitleField[dt]
	// Meta judul belum dimuat → tunggu (JANGAN cache kode dulu, biar tak nyangkut).
	if (titleField === undefined) return
	if (titleField === null) {
		// name sudah readable (mis. Data Pekerjaan, List Status Rumah).
		linkTitles[key] = String(value)
		return
	}
	try {
		const params = new URLSearchParams({
			doctype: dt,
			fieldname: titleField,
			filters: String(value),
		})
		const res = await fetch(`/api/method/frappe.client.get_value?${params.toString()}`, {
			method: 'GET',
			credentials: 'include',
			headers: { Accept: 'application/json' },
		})
		const json = await res.json()
		const msg = json.message
		const title = msg && typeof msg === 'object' ? msg[titleField] : msg
		saveLinkTitle(key, title != null && title !== '' ? title : String(value))
	} catch (e) {
		linkTitles[key] = String(value)
	}
}

// Resolusi semua field Link pada dokumen aktif.
function resolveAllLinks() {
	for (const f of metaFields.value) {
		if (f.fieldtype === 'Link' && f.options && form[f.fieldname]) {
			resolveLinkTitle(f.options, form[f.fieldname])
		}
	}
}

// Nilai tampilan untuk field Link: judul kanonik dari opsi (case-insensitive),
// lalu hasil resolusi title, terakhir kode mentah.
function linkDisplay(field) {
	const v = form[field.fieldname]
	if (!v) return ''
	const opts = linkOptions[field.options]
	if (opts) {
		const cur = opts.find((o) => String(o.value).toLowerCase() === String(v).toLowerCase())
		if (cur) return cur.label
	}
	const t = linkTitles[`${field.options}:${v}`]
	if (t !== undefined) return t
	// Belum ter-resolve. Doctype tanpa title_field (name readable) → tampilkan value.
	// Selain itu (punya title_field / meta belum siap) → '…' biar tak kedip kode.
	if (linkTitleField[field.options] === null) return v
	return '…'
}

// ---- Kontrol Link searchable (judul di tombol; cari ke master di panel) -----
const openDropdown = ref('') // fieldname Link yang panelnya terbuka
// Arah buka dropdown: true = ke atas (saat ruang di bawah trigger tidak cukup,
// mis. field terakhir "Data Kendaraan" yang tertutup tombol Save).
const dropUp = ref(false)
const linkSearch = ref('')
const linkResults = ref([])
const linkSearchLoading = ref(false)

// Cocokkan nilai dgn opsi case-insensitive (data bisa beda case).
function optionMatch(opt, field) {
	const v = form[field.fieldname]
	if (v == null || v === '') return false
	return String(opt.value).toLowerCase() === String(v).toLowerCase()
}

// Filter bawaan Link dari Frappe (`link_filters`) → array [field, op, value] utk
// dikirim ke get_list, supaya opsi yang tampil SAMA dengan desk (mis. hanya data
// `aktif=1`). Tanpa ini, opsi non-aktif ikut muncul lalu ditolak server. Kondisi
// dinamis (eval:/referensi doc) dilewati karena tak bisa dievaluasi di klien.
// Cascade filter domisili — meniru client script desk "Dynamic Select Domisili".
// provinsi_domisili fixed "Kepulauan Riau" (kode 21): Kota difilter provinsi,
// Kecamatan difilter kota terpilih, Kelurahan difilter kecamatan (+kota guard)
// terpilih. Nilai '' saat parent belum dipilih → hasil kosong (paksa urutan isi).
const PROV_CODE_DOMISILI = '21' // Kepulauan Riau
const domisiliFilters = {
	kota_domisili: () => [['kode_provinsi', '=', PROV_CODE_DOMISILI]],
	kecamatan_domisili: () => [['kode_kab_kota', '=', form.kota_domisili || '']],
	kelurahan_domisili: () => [
		['kode_kecamatan', '=', form.kecamatan_domisili || ''],
		['kode_kab_kota', '=', form.kota_domisili || ''],
	],
	kota_domisili_pps: () => [['kode_provinsi', '=', PROV_CODE_DOMISILI]],
	kecamatan_domisili_pps: () => [['kode_kab_kota', '=', form.kota_domisili_pps || '']],
	kelurahan_domisili_pps: () => [
		['kode_kecamatan', '=', form.kecamatan_domisili_pps || ''],
		['kode_kab_kota', '=', form.kota_domisili_pps || ''],
	],
}
// Parent berubah → kosongkan turunannya (spt set_value(null) di client script desk).
const domisiliChildren = {
	kota_domisili: ['kecamatan_domisili', 'kelurahan_domisili'],
	kecamatan_domisili: ['kelurahan_domisili'],
	kota_domisili_pps: ['kecamatan_domisili_pps', 'kelurahan_domisili_pps'],
	kecamatan_domisili_pps: ['kelurahan_domisili_pps'],
}

function linkFilters(field) {
	const out = []
	const push = (f, op, v) => {
		const isDyn = typeof v === 'string' && /^eval:|^doc\./.test(v.trim())
		if (!isDyn) {
			out.push([f, op, v])
			return
		}
		// Resolusi nilai DINAMIS terhadap form (mis. "eval: doc.tenor" → nilai tenor
		// terpilih) supaya filter ikut nilai form — mis. Skema Pinjaman hanya tenor
		// yang dipilih. Belum ada nilai (tenor belum dipilih) → filter dilewati.
		let val
		try {
			const s = v.trim()
			// eslint-disable-next-line no-new-func
			val = s.startsWith('eval:')
				? new Function('doc', `return (${s.slice(5)})`)(form)
				: form[s.slice(4)]
		} catch (e) {
			val = undefined
		}
		if (val === undefined || val === null || val === '') return
		out.push([f, op, val])
	}
	// Filter bawaan Link dari Frappe (`link_filters`).
	let raw = field.link_filters
	if (raw) {
		try {
			if (typeof raw === 'string') raw = JSON.parse(raw)
		} catch (e) {
			raw = null
		}
		if (Array.isArray(raw)) {
			for (const c of raw) {
				if (!Array.isArray(c)) continue
				if (c.length === 4) push(c[1], c[2], c[3])
				else if (c.length === 3) push(c[0], c[1], c[2])
			}
		} else if (raw && typeof raw === 'object') {
			for (const [k, v] of Object.entries(raw)) push(k, '=', v)
		}
	}
	// Cascade domisili (tak ada di link_filters doctype; disetel via client script desk).
	const dom = domisiliFilters[field.fieldname]
	if (dom) out.push(...dom())
	return out
}

// Buka/tutup panel + siapkan hasil awal (list kecil = preload, besar = fetch).
// Perkiraan tinggi panel dropdown (search box + list max-h-56). Dipakai untuk
// memutuskan buka ke atas / ke bawah agar tidak tertutup tombol Save.
const DROPDOWN_EST_HEIGHT = 300
function toggleLinkDropdown(field, event) {
	if (openDropdown.value === field.fieldname) {
		openDropdown.value = ''
		return
	}
	// Tentukan arah: kalau ruang di bawah trigger kurang DAN ruang di atas lebih
	// lega, buka ke atas. Ini yang mencegah dropdown menutupi tombol Save.
	const rect = event?.currentTarget?.getBoundingClientRect?.()
	if (rect) {
		const spaceBelow = window.innerHeight - rect.bottom
		const spaceAbove = rect.top
		dropUp.value = spaceBelow < DROPDOWN_EST_HEIGHT && spaceAbove > spaceBelow
	} else {
		dropUp.value = false
	}
	openDropdown.value = field.fieldname
	linkSearch.value = ''
	// Field dgn link_filters / motor_tarikan → selalu fetch (jangan pakai cache generik).
	const opts =
		field.fieldname === 'motor_tarikan' || linkFilters(field).length
			? null
			: linkOptions[field.options]
	if (opts) linkResults.value = opts
	else fetchLinkResults(field, '')
}

// Ambil hasil dari master (Link besar / saat ketik).
async function fetchLinkResults(field, query) {
	// Unit internal → query terfilter dealer (get_mokas_unit_query), bukan get_list.
	if (field.fieldname === 'motor_tarikan') return fetchMokasUnits(query)
	const dt = field.options
	const titleField = linkTitleField[dt]
	linkSearchLoading.value = true
	linkResults.value = []
	try {
		const flds = titleField ? ['name', titleField] : ['name']
		const params = new URLSearchParams({
			doctype: dt,
			fields: JSON.stringify(flds),
			limit_page_length: '20',
			order_by: 'name asc',
		})
		const lf = linkFilters(field)
		if (lf.length) params.set('filters', JSON.stringify(lf))
		if (query) {
			const ors = [['name', 'like', `%${query}%`]]
			if (titleField) ors.push([titleField, 'like', `%${query}%`])
			params.set('or_filters', JSON.stringify(ors))
		}
		const res = await fetch(`/api/method/frappe.client.get_list?${params.toString()}`, {
			method: 'GET',
			credentials: 'include',
			headers: { Accept: 'application/json' },
		})
		const json = await res.json()
		const recs = json.message || []
		linkResults.value = recs.map((r) => ({
			value: String(r.name),
			label: (titleField && r[titleField]) || String(r.name),
		}))
	} catch (e) {
		linkResults.value = []
	} finally {
		linkSearchLoading.value = false
	}
}

// Saat ketik: list kecil → filter lokal; besar → query backend (debounce).
let linkSearchTimer = null
function onLinkSearch(field) {
	const q = linkSearch.value.trim()
	const opts =
		field.fieldname === 'motor_tarikan' || linkFilters(field).length
			? null
			: linkOptions[field.options]
	if (opts) {
		const ql = q.toLowerCase()
		linkResults.value = ql
			? opts.filter(
					(o) =>
						o.label.toLowerCase().includes(ql) ||
						String(o.value).toLowerCase().includes(ql)
			  )
			: opts
		return
	}
	clearTimeout(linkSearchTimer)
	linkSearchTimer = setTimeout(() => fetchLinkResults(field, q), 300)
}

// Tiru perilaku `fetch_from` Frappe: saat sebuah Link berubah, langsung isi
// field turunannya dari dokumen tertaut TANPA perlu save (persis form desk).
// Mis. pinjam ← skema_pinjaman.pinjaman, angsuran ← skema_pinjaman.angsuran.
async function applyFetchFrom(linkField, value) {
	const prefix = `${linkField.fieldname}.`
	const targets = metaFields.value.filter(
		(f) => typeof f.fetch_from === 'string' && f.fetch_from.startsWith(prefix)
	)
	if (!targets.length) return
	// Link dikosongkan → kosongkan juga field turunannya.
	if (!value) {
		for (const t of targets) form[t.fieldname] = null
		return
	}
	const sourceFields = targets.map((t) => t.fetch_from.slice(prefix.length))
	try {
		const params = new URLSearchParams({
			doctype: linkField.options,
			filters: JSON.stringify({ name: value }),
			fieldname: JSON.stringify(sourceFields),
		})
		const res = await fetch(`/api/method/frappe.client.get_value?${params.toString()}`, {
			method: 'GET',
			credentials: 'include',
			headers: { Accept: 'application/json' },
		})
		if (!res.ok) return
		const data = (await res.json())?.message || {}
		for (const t of targets) {
			const src = t.fetch_from.slice(prefix.length)
			if (src in data) form[t.fieldname] = data[src]
		}
	} catch (e) {
		/* abaikan — nilai tetap akan ikut terisi server saat save (fallback) */
	}
}

function selectLink(field, value, label) {
	const prev = form[field.fieldname]
	form[field.fieldname] = value
	if (label != null) linkTitles[`${field.options}:${value}`] = label
	openDropdown.value = ''
	// Isi otomatis field ber-fetch_from (mis. Pinjaman & Angsuran dari Skema Pinjaman).
	applyFetchFrom(field, value)
	// Cascade domisili: parent berubah → kosongkan turunannya (spt client script desk).
	if (prev !== value) {
		const children = domisiliChildren[field.fieldname]
		if (children) for (const c of children) form[c] = null
	}
}

// ---- Unit internal (MOKAS) — paritas data_pengajuan.js -----------------------
// Field `motor_tarikan` (Unit Internal) hanya relevan bila pengajuan berasal dari
// dealer mokas KITA SENDIRI (nama_dealer terdaftar di Single "Pengaturan Dealer
// Bengkel"). Hasilnya dicerminkan ke flag hidden `is_dealer_mokas` yang dipakai
// depends_on field motor_tarikan.
const dealerMokasList = ref(null)
const dealerReady = ref(false)
async function loadDealerMokasList() {
	if (dealerMokasList.value) return dealerMokasList.value
	try {
		const res = await fetch(
			'/api/method/juragan.bengkel.dealer.get_dealer_mokas_list',
			{ method: 'GET', credentials: 'include', headers: { Accept: 'application/json' } }
		)
		const json = await res.json()
		dealerMokasList.value = Array.isArray(json.message) ? json.message : []
	} catch (e) {
		dealerMokasList.value = []
	}
	return dealerMokasList.value
}
// Hitung is_dealer_mokas = (kategori MOKAS && nama_dealer terdaftar). `clearUnit`
// dimatikan saat pemuatan awal supaya tidak mengubah unit tersimpan hanya untuk
// tampilan; saat user mengubah dealer/kategori → unit tak valid dikosongkan.
async function syncDealerMokasFlag({ clearUnit = true } = {}) {
	const list = await loadDealerMokasList()
	const isMokas =
		form.kategori === 'MOKAS' && !!form.nama_dealer && list.includes(form.nama_dealer)
	const flag = isMokas ? 1 : 0
	if (Number(form.is_dealer_mokas || 0) !== flag) form.is_dealer_mokas = flag
	if (!isMokas && clearUnit && form.motor_tarikan) form.motor_tarikan = ''
}
// Guard blacklist: dealer ber-status Blacklist tidak boleh dipakai → peringatkan
// & kosongkan (persis handler nama_dealer di desk).
async function checkDealerBlacklist() {
	if (!form.nama_dealer) return
	try {
		const params = new URLSearchParams({
			doctype: 'Data Mokas',
			filters: JSON.stringify({ name: form.nama_dealer }),
			fieldname: JSON.stringify(['blacklist', 'nama_mokas']),
		})
		const res = await fetch(`/api/method/frappe.client.get_value?${params.toString()}`, {
			method: 'GET',
			credentials: 'include',
			headers: { Accept: 'application/json' },
		})
		const msg = (await res.json())?.message || {}
		if (msg.blacklist) {
			notifyError(
				`Dealer ${msg.nama_mokas || form.nama_dealer} sedang berstatus Blacklist dan tidak dapat digunakan untuk pengajuan.`,
				'Dealer Blacklist'
			)
			form.nama_dealer = ''
		}
	} catch (e) {
		/* abaikan — validasi final tetap di server */
	}
}
// Autofill data unit saat motor_tarikan dipilih (get_unit_detail). Meng-overwrite
// nilai yang ada, persis autofill_from_unit desk.
async function autofillFromUnit() {
	if (!form.motor_tarikan) return
	try {
		const res = await fetch(
			`/api/method/juragan.juragan.doctype.data_pengajuan.data_pengajuan.get_unit_detail?motor_tarikan=${encodeURIComponent(
				form.motor_tarikan
			)}`,
			{ method: 'GET', credentials: 'include', headers: { Accept: 'application/json' } }
		)
		const data = (await res.json())?.message || {}
		for (const k of Object.keys(data)) {
			const v = data[k]
			if (v !== null && v !== undefined && v !== '') form[k] = v
		}
	} catch (e) {
		/* abaikan */
	}
}
// kategori END USER tidak memakai dealer → kosongkan nama_dealer.
function clearEndUserNamaDealer() {
	if ((form.kategori || '').trim().toUpperCase() === 'END USER' && form.nama_dealer) {
