// Dropdown motor_tarikan: unit terfilter server (posisi dealer + Kredit + leasing
// internal) via get_mokas_unit_query — bukan get_list generik.
async function fetchMokasUnits(query) {
	linkSearchLoading.value = true
	linkResults.value = []
