// Watcher dealer. applyingRemote → abaikan (perubahan dari server, bukan user);
// dealerReady → aktif setelah dokumen awal termuat.
watch(
	() => form.kategori,
	() => {
		if (applyingRemote.value || !dealerReady.value) return
		clearEndUserNamaDealer()
		syncDealerMokasFlag()
	}
)
watch(
	() => form.nama_dealer,
	() => {
