	}
)

// Ambil meta doctype (getdoctype = whitelist, aman untuk user portal).
async function loadMeta() {
	try {
		const res = await fetch(
			`/api/method/frappe.desk.form.load.getdoctype?doctype=${encodeURIComponent(
				'Data Pengajuan'
			)}`,
			{ method: 'GET', credentials: 'include', headers: { Accept: 'application/json' } }
		)
		if (!res.ok) throw new Error(`HTTP ${res.status}`)
		const json = await res.json()
		const docs = json.docs || json.message?.docs || []
		const dt = docs.find((x) => x.name === 'Data Pengajuan') || docs[0]
		metaFields.value = (dt && dt.fields) || []
		// activeSubtab di-set lewat watcher dataTabs (pilih tab pertama yang punya
		// field terlihat) — perlu menunggu permlevel access selesai dimuat.
		// Link meta di-load di BACKGROUND — jangan blok pengisian form. Judul Link
		// ter-resolve (di dalam loadLinkMeta, fase 1) & update reaktif belakangan.
		loadLinkMeta().catch(() => {})
	} catch (e) {
		metaError.value = e.message || String(e)
	}
}

