	comments.showForm = false
	comments.body = ''
}

// ---- Attachments: upload File Kredit + child table File Pendukung ----------
// Helper umum: upload satu file → kembalikan File doc ({ file_url, ... }).
// Pakai endpoint Frappe standar /api/method/upload_file (butuh CSRF token).
async function uploadRawFile(file, { fieldname = '', isPrivate = 1 } = {}) {
	const fd = new FormData()
	fd.append('file', file, file.name)
	fd.append('is_private', String(isPrivate))
	fd.append('doctype', 'Data Pengajuan')
	fd.append('docname', name.value)
	// fieldname → Frappe otomatis set field Attach di dokumen induk & menyimpannya.
	if (fieldname) fd.append('fieldname', fieldname)
	const res = await fetch('/api/method/upload_file', {
		method: 'POST',
		credentials: 'include',
		// JANGAN set Content-Type → biar browser pasang boundary multipart.
		headers: { Accept: 'application/json', 'X-Frappe-CSRF-Token': window.csrf_token || '' },
		body: fd,
	})
	const json = await res.json().catch(() => ({}))
	if (!res.ok) throw new Error(frappeError(json) || `HTTP ${res.status}`)
	return json.message
}

// Simpan dokumen via frappe.client.save (POST → butuh CSRF).
async function saveDoc(docObj) {
	const res = await fetch('/api/method/frappe.client.save', {
		method: 'POST',
		credentials: 'include',
		headers: {
			'Content-Type': 'application/json',
			Accept: 'application/json',
			'X-Frappe-CSRF-Token': window.csrf_token || '',
		},
		body: JSON.stringify({ doc: docObj }),
	})
	const json = await res.json().catch(() => ({}))
	if (!res.ok) throw new Error(frappeError(json) || `HTTP ${res.status}`)
	return json.message
}

// Batas & validasi file (ekstensi + ukuran). `exts` = daftar ekstensi yang boleh.
const MAX_FILE_MB = 3
function validateFile(file, exts) {
	const ext = (file.name.split('.').pop() || '').toLowerCase()
	if (!exts.includes(ext)) {
		return `Format file harus ${exts.map((e) => e.toUpperCase()).join(', ')}.`
	}
	if (file.size > MAX_FILE_MB * 1024 * 1024) {
		return `Ukuran file maksimal ${MAX_FILE_MB} MB.`
	}
	return ''
}

// --- File Kredit (field Attach: ktp / ktp_2 / ktp_3) — hanya PDF ---
const kreditInput = ref(null)
const pendingKreditField = ref(null)
const kreditUploading = ref('')
const kreditDeleting = ref('')
const kreditError = ref('')

// Hapus File Kredit → kosongkan nilai field (staged; benar-benar tersimpan saat Save).
function deleteKreditFile(f) {
	if (isAttachReadOnly(f)) return
	askConfirm(`Hapus file pada "${f.label}"?`, () => {
		kreditError.value = ''
		form[f.fieldname] = '' // tandai dirty → tombol Save muncul
	})
}

// Terkunci bila field read-only (read_only statis / read_only_depends_on ikut status).
function isAttachReadOnly(f) {
	return isFieldReadOnly(f)
}

function triggerKreditPick(f) {
	if (isAttachReadOnly(f)) return
	pendingKreditField.value = f
	kreditError.value = ''
	if (kreditInput.value) {
		kreditInput.value.value = '' // reset → file yang sama bisa dipilih ulang
		kreditInput.value.click()
	}
}

async function onKreditFileChange(e) {
	const file = e.target.files && e.target.files[0]
	const f = pendingKreditField.value
	if (!file || !f) return
	// Hanya PDF, maks 3 MB.
	const verr = validateFile(file, ['pdf'])
	if (verr) {
		kreditError.value = `${f.label}: ${verr}`
		pendingKreditField.value = null
		return
	}
	kreditUploading.value = f.fieldname
	kreditError.value = ''
	try {
		// Upload fisik file saja (tanpa fieldname → tidak langsung di-set ke dokumen).
		// Nilai field di-stage ke form → tersimpan saat user menekan Save.
		const fileDoc = await uploadRawFile(file, { isPrivate: 1 })
		form[f.fieldname] = fileDoc.file_url // tandai dirty
	} catch (err) {
		kreditError.value = err.message || String(err)
		notifyError(err, 'Gagal mengunggah file')
	} finally {
		kreditUploading.value = ''
		pendingKreditField.value = null
	}
}

// --- File Pendukung (child table table_otkl → "File Upload Data Pendukung") ---
const pendukungInput = ref(null)
const pendukung = reactive({
	namaFile: '',
	submitting: false,
	error: '',
})
// Opsi Nama File → master "File Tambahan Data Pengajuan" (name = nama file).
const pendukungOptions = ref([])

function resetPendukungForm() {
	pendukung.namaFile = ''
	pendukung.error = ''
	if (pendukungInput.value) pendukungInput.value.value = ''
}

function triggerPendukungPick() {
	if (!pendukungEditable.value) return // hanya saat Draft & mode edit
	if (pendukungInput.value) {
		pendukungInput.value.value = ''
		pendukungInput.value.click()
	}
}

// Pilih file → LANGSUNG upload + tambah baris (tanpa tombol Tambah).
// Syarat: Nama File sudah dipilih; file JPG/PNG/PDF maks 3 MB.
async function onPendukungFileChange(e) {
	const file = e.target.files && e.target.files[0]
	if (!file) return
	if (!pendukungEditable.value) return // jaga-jaga: hanya saat Draft & mode edit
	pendukung.error = ''
	if (!pendukung.namaFile) {
		pendukung.error = 'Pilih Nama File terlebih dulu.'
		if (pendukungInput.value) pendukungInput.value.value = ''
		return
	}
	const verr = validateFile(file, ['jpg', 'jpeg', 'png', 'pdf'])
	if (verr) {
		pendukung.error = verr
		if (pendukungInput.value) pendukungInput.value.value = ''
		return
	}
	pendukung.submitting = true
	try {
		const fileDoc = await uploadRawFile(file, { isPrivate: 1 })
		if (!Array.isArray(form.table_otkl)) form.table_otkl = []
		form.table_otkl.push({
			doctype: 'File Upload Data Pendukung',
			parentfield: 'table_otkl',
			parenttype: 'Data Pengajuan',
			nama_file: pendukung.namaFile,
			upload_file_pdf_png_jpg: fileDoc.file_url,
		}) // tandai dirty → tombol Save muncul
		resetPendukungForm()
	} catch (e2) {
		pendukung.error = e2.message || String(e2)
		notifyError(e2, 'Gagal mengunggah file pendukung')
	} finally {
		pendukung.submitting = false
	}
}

