// Meniru desk (data_pengajuan.js) untuk resolusi print format & URL download.
const formHasilOpen = ref(false)

// Tombol Form Hasil HANYA muncul pada status: CA Approved, CA Rejected,
// Banding Approved, Banding Rejected.
const FORM_HASIL_STATUSES = new Set([
	'CA Approved',
	'CA Rejected',
	'Banding Approved',
	'Banding Rejected',
])
const showFormHasil = computed(() => FORM_HASIL_STATUSES.has((doc.data?.status || '').trim()))

// Print format "Internal" mengikuti logika desk: CA → "Form Hasil CA",
// Banding → "Form Hasil Banding". Untuk "Sudah Pencairan" ikut keputusan
// (CA Approve → Form Hasil CA; CA Reject + Banding Approve → Form Hasil Banding).
// Fallback → "Form Hasil CA". Eksternal selalu "Surat Persetujuan Pembiayaan".
const internalPrintFormat = computed(() => {
	const status = (doc.data?.status || '').trim()
	const MAP = {
		'CA Approved': 'Form Hasil CA',
		'CA Rejected': 'Form Hasil CA',
		'Banding Approved': 'Form Hasil Banding',
		'Banding Rejected': 'Form Hasil Banding',
	}
	let fmt = MAP[status]
	if (status === 'Sudah Pencairan') {
		const ca = doc.data?.keputusan_credit_analyst
		const banding = doc.data?.keputusan_banding
		if (ca === 'Approve') fmt = 'Form Hasil CA'
		else if (ca === 'Reject' && banding === 'Approve') fmt = 'Form Hasil Banding'
	}
	return fmt || 'Form Hasil CA'
})

// Dua pilihan di bottom-sheet Form Hasil (label + print format).
const formHasilOptions = computed(() => [
	{ label: 'Download PDF Internal', format: internalPrintFormat.value },
	{ label: 'Download PDF Eksternal', format: 'Surat Persetujuan Pembiayaan' },
])

// Buka PDF di viewer in-app (PDF.js). URL endpoint PERSIS seperti desk
// (frappe.utils.print_format.download_pdf), TAPI ditampilkan lewat PdfViewer
// bukan window.open: endpoint download_pdf memakai Content-Disposition
// "attachment" + WebView Android tak punya renderer PDF → window.open hanya
// menghasilkan halaman kosong tanpa error. PDF.js mengambil byte-nya langsung
// (with credentials) & merender di layar.
function openFormHasilPdf(printFormat, label) {
	const url =
		`/api/method/frappe.utils.print_format.download_pdf` +
		`?doctype=${encodeURIComponent('Data Pengajuan')}` +
		`&name=${encodeURIComponent(name.value)}` +
		`&format=${encodeURIComponent(printFormat)}` +
		`&no_letterhead=0`
	openPdf(url, label || printFormat)
	formHasilOpen.value = false
}

