// Print format Surat Diskresi per tipe (samakan dengan print_format_rules di
// Document Signing Config). Sebelumnya di sini dipakai nama "Form Surat Diskresi"
// yang TIDAK ADA — Frappe tidak error untuk format tak dikenal, ia diam-diam
// jatuh ke print format "Standard", jadi yang keluar PDF generik (±20 KB)
// alih-alih form asli (±66 KB).
const DISKRESI_PRINT_FORMATS = {
	'Kelengkapan Berkas': 'Surat Diskresi Kelengkapan Berkas QR',
	'Pengurangan Angsuran': 'Surat Diskresi Pengurangan Angsuran QR',
}

// Buka PDF Surat Diskresi di viewer in-app. Mengikuti surat_diskresi.js desk:
// utamakan PDF bertanda tangan dari Document Signing Log; kalau dokumennya
// disetujui sebelum signing config ada, fallback render print format sesuai tipe.
async function downloadDiskresiPdf(diskresi) {
	const row = typeof diskresi === 'string' ? { name: diskresi } : diskresi || {}
	let fileUrl = ''
	try {
		const params = new URLSearchParams({
			reference_doctype: 'Surat Diskresi',
			reference_name: row.name,
		})
		const res = await fetch(
			`/api/method/juragan.juragan.doctype.document_signing_log.document_signing_log.get_latest_signed_pdf?${params.toString()}`,
			{ method: 'GET', credentials: 'include', headers: { Accept: 'application/json' } }
		)
		if (res.ok) fileUrl = (await res.json().catch(() => ({})))?.message || ''
	} catch (e) {
		// Signed PDF tak terjangkau → lanjut render live di bawah.
	}
	if (!fileUrl) {
		const fmt =
			DISKRESI_PRINT_FORMATS[row.tipe_diskresi] ||
			DISKRESI_PRINT_FORMATS['Kelengkapan Berkas']
		fileUrl =
			`/api/method/frappe.utils.print_format.download_pdf` +
			`?doctype=${encodeURIComponent('Surat Diskresi')}` +
			`&name=${encodeURIComponent(row.name)}` +
			`&format=${encodeURIComponent(fmt)}` +
			`&no_letterhead=0`
	}
	openPdf(fileUrl, row.name)
}

// --- Modal buat Surat Diskresi (field meniru dialog desk) ---
const diskresiCreate = reactive({
	open: false,
	tipe: '',
	nominal: '',
	filePendukung: '',
	alasan: '',
	uploading: false,
	submitting: false,
	error: '',
})
const kategoriDiskresiOptions = ref([])
const diskresiFileInput = ref(null)

const isDiskresiPengurangan = computed(() => diskresiCreate.tipe === TIPE_PENGURANGAN)
// Angsuran Baru = angsuran pengajuan − nominal pengurangan (≥ 0), dihitung reaktif.
const diskresiAngsuranBaru = computed(() => {
	const angsuran = Number(doc.data?.angsuran || 0)
	const nominal = Number(diskresiCreate.nominal || 0)
	return Math.max(0, angsuran - nominal)
})

// Opsi Tipe Diskresi = master "Kategori Diskresi" (jenis "Data Pengajuan").
// Lewat endpoint portal khusus: master ini hanya readable System Manager, jadi
// get_list biasa mengembalikan kosong untuk user pembuat diskresi (mis. Admin OPS).
async function loadKategoriDiskresi() {
	if (kategoriDiskresiOptions.value.length) return
	try {
		const params = new URLSearchParams({ jenis: 'Data Pengajuan' })
		const res = await fetch(
			`/api/method/juragan.api.portal.surat_diskresi.get_kategori_diskresi?${params.toString()}`,
			{ method: 'GET', credentials: 'include', headers: { Accept: 'application/json' } }
		)
		const json = await res.json()
		kategoriDiskresiOptions.value = json.message || []
	} catch (e) {
		kategoriDiskresiOptions.value = []
	}
}

function openDiskresiCreate() {
	diskresiCreate.tipe = ''
	diskresiCreate.nominal = ''
	diskresiCreate.filePendukung = ''
	diskresiCreate.alasan = ''
	diskresiCreate.error = ''
	diskresiCreate.open = true
	loadKategoriDiskresi()
	loadDiskresiList()
}
function closeDiskresiCreate() {
	if (diskresiCreate.submitting) return
	diskresiCreate.open = false
}

// Simpan angka mentah saat blur, tampilkan terformat (reuse helper currency).
function onDiskresiNominalBlur(e) {
	const n = parseCurrency(e.target.value)
	diskresiCreate.nominal = n === '' ? '' : n
	e.target.value = currencyDisplay(diskresiCreate.nominal)
}

function triggerDiskresiFilePick() {
	if (diskresiFileInput.value) {
		diskresiFileInput.value.value = ''
		diskresiFileInput.value.click()
	}
}
async function onDiskresiFileChange(e) {
	const file = e.target.files && e.target.files[0]
	if (!file) return
	const verr = validateFile(file, ['jpg', 'jpeg', 'png', 'pdf'])
	if (verr) {
		diskresiCreate.error = verr
		return
	}
	diskresiCreate.uploading = true
	diskresiCreate.error = ''
	try {
		const fileDoc = await uploadRawFile(file, { isPrivate: 1 })
		diskresiCreate.filePendukung = fileDoc.file_url
	} catch (err) {
		diskresiCreate.error = err.message || String(err)
	} finally {
		diskresiCreate.uploading = false
	}
}

// Buat Surat Diskresi via whitelist create_from_pengajuan (validasi meniru desk).
async function submitDiskresi() {
	diskresiCreate.error = ''
	const tipe = (diskresiCreate.tipe || '').trim()
	if (!tipe) {
		diskresiCreate.error = 'Tipe Diskresi wajib diisi.'
		return
	}
	if (!diskresiCreate.alasan.trim()) {
		diskresiCreate.error = 'Keterangan wajib diisi.'
		return
	}
	if (isDiskresiPengurangan.value) {
		const angsuran = Number(doc.data?.angsuran || 0)
		const nominal = Number(diskresiCreate.nominal || 0)
		if (nominal <= 0) {
			diskresiCreate.error =
				'Nominal Pengurangan wajib diisi untuk tipe Pengurangan Angsuran.'
			return
		}
		if (angsuran - nominal <= 0) {
			diskresiCreate.error = `Angsuran Baru harus lebih dari 0. Pastikan Nominal Pengurangan tidak lebih dari atau sama dengan Angsuran (${currencyDisplay(
				angsuran
			)}).`
			return
		}
	}
	diskresiCreate.submitting = true
	try {
		const res = await fetch(
			'/api/method/juragan.juragan.doctype.surat_diskresi.surat_diskresi.create_from_pengajuan',
			{
				method: 'POST',
				credentials: 'include',
				headers: {
					'Content-Type': 'application/json',
					Accept: 'application/json',
					'X-Frappe-CSRF-Token': window.csrf_token || '',
				},
				body: JSON.stringify({
					data_pengajuan: name.value,
					tipe_diskresi: tipe,
					alasan_diskresi: diskresiCreate.alasan,
					nominal_pengurangan: isDiskresiPengurangan.value
						? Number(diskresiCreate.nominal || 0)
						: 0,
					file_pendukung: diskresiCreate.filePendukung || null,
				}),
			}
		)
		const json = await res.json().catch(() => ({}))
		if (!res.ok) throw new Error(frappeError(json) || `HTTP ${res.status}`)
		diskresiCreate.open = false
		await loadDiskresiList()
		loadActivity()
		notifySuccess('Surat Diskresi berhasil dibuat.')
	} catch (e) {
		diskresiCreate.error = e.message || String(e)
		notifyError(e, 'Gagal membuat Surat Diskresi')
	} finally {
		diskresiCreate.submitting = false
	}
}

// ---- Workflow Flow Kredit (transisi state per role) ------------------------
const actionsOpen = ref(false)
const transitions = reactive({ loading: false, items: [], applying: '', error: '' })

// Pesan error Frappe yang manusiawi dari response.
function frappeError(json) {
	try {
		if (json && json._server_messages) {
			const arr = JSON.parse(json._server_messages)
			return arr
				.map((m) => {
					try {
						return JSON.parse(m).message
					} catch (e) {
						return m
					}
				})
				.join('\n')
		}
	} catch (e) {
		/* ignore */
	}
	return (json && (json.exception || json.message)) || ''
}

// Daftar transisi valid dari state sekarang sesuai role user (endpoint Frappe).
async function loadTransitions() {
	if (!doc.data) return
	transitions.loading = true
	try {
		const res = await fetch('/api/method/frappe.model.workflow.get_transitions', {
			method: 'POST',
			credentials: 'include',
			headers: {
				'Content-Type': 'application/json',
				Accept: 'application/json',
				'X-Frappe-CSRF-Token': window.csrf_token || '',
			},
			body: JSON.stringify({ doc: doc.data }),
		})
		const json = await res.json()
		transitions.items = json.message || []
	} catch (e) {
		transitions.items = []
	} finally {
		transitions.loading = false
	}
}

// Terapkan aksi workflow → server pindah state, lalu refresh dok/timeline/transisi.
async function applyAction(action) {
	transitions.applying = action
	transitions.error = ''
	try {
		const res = await fetch('/api/method/frappe.model.workflow.apply_workflow', {
			method: 'POST',
			credentials: 'include',
			headers: {
				'Content-Type': 'application/json',
				Accept: 'application/json',
				'X-Frappe-CSRF-Token': window.csrf_token || '',
			},
			body: JSON.stringify({ doc: doc.data, action }),
		})
		const json = await res.json().catch(() => ({}))
		if (!res.ok) throw new Error(frappeError(json) || `HTTP ${res.status}`)
		actionsOpen.value = false
		await doc.fetch()
		await syncFormFromDoc()
		loadActivity()
		loadTransitions()
		notifySuccess(`Aksi "${action}" berhasil diterapkan.`)
	} catch (e) {
		transitions.error = e.message || String(e)
		actionsOpen.value = false
		notifyError(e, `Gagal menerapkan aksi "${action}"`)
	} finally {
		transitions.applying = ''
	}
}

// ---- Input tambahan sebelum aksi workflow (meniru desk before_workflow_action) --
// Sebagian aksi butuh input dulu lewat modal, baru aksinya dijalankan:
//   - APPEAL (Ajukan Banding / Rekom Banding / Tidak Rekom Banding) → alasan_banding
//   - REJECT (Reject)                                               → banding_ke (PIC)
//   - CANCEL (Cancel Approval)                                      → keterangan_cancel_approval
// Pencocokan EXACT (lowercase) — persis logika desk (data_pengajuan.js).
const REJECT_KEYS = ['reject', 'tolak']
const APPEAL_KEYS = ['ajukan banding', 'rekom banding', 'tidak rekom banding']
const CANCEL_KEYS = ['cancel approval']

const wfInput = reactive({
	open: false,
	action: '',
	kind: '', // 'alasan' | 'pic' | 'cancel'
	title: '',
	label: '',
	value: '', // untuk alasan / keterangan (textarea)
	pic: '', // untuk banding_ke (Link)
	picOptions: [],
	picLoading: false,
	error: '',
	submitting: false,
})

// Gerbang klik tombol aksi: buka modal input dulu bila perlu, kalau tidak langsung apply.
function onActionClick(action) {
	const act = String(action).trim().toLowerCase()
	if (APPEAL_KEYS.includes(act)) openWfInput(action, 'alasan')
	else if (REJECT_KEYS.includes(act)) openWfInput(action, 'pic')
	else if (CANCEL_KEYS.includes(act)) openWfInput(action, 'cancel')
	else applyAction(action)
}

function openWfInput(action, kind) {
	wfInput.action = action
	wfInput.kind = kind
	wfInput.value = ''
	wfInput.pic = ''
	wfInput.error = ''
	if (kind === 'alasan') {
		wfInput.title = 'Alasan Banding'
		wfInput.label = 'Alasan Banding'
		wfInput.value = doc.data?.alasan_banding || ''
	} else if (kind === 'cancel') {
		wfInput.title = 'Keterangan Cancel Approval'
		wfInput.label = 'Alasan Pembatalan'
		wfInput.value = doc.data?.keterangan_cancel_approval || ''
	} else if (kind === 'pic') {
		wfInput.title = 'Pilih Tujuan Banding'
		wfInput.label = 'Banding Ke'
		wfInput.pic = doc.data?.banding_ke || ''
		loadPicBandingOptions()
	}
	actionsOpen.value = false
	wfInput.open = true
}

// Opsi PIC Banding = User Juragan dengan profile_completed & pic_banding (sama filter desk).
async function loadPicBandingOptions() {
	wfInput.picLoading = true
	wfInput.picOptions = []
	try {
		const params = new URLSearchParams({
			doctype: 'User Juragan',
			// value = name (user_id/email, disimpan ke banding_ke) tapi label = nama_lengkap
			// (title_field User Juragan) supaya tampil nama, bukan email.
			fields: JSON.stringify(['name', 'nama_lengkap']),
			filters: JSON.stringify([
				['profile_completed', '=', 1],
				['pic_banding', '=', 1],
			]),
			limit_page_length: '0',
			order_by: 'nama_lengkap asc',
		})
		const res = await fetch(`/api/method/frappe.client.get_list?${params.toString()}`, {
			method: 'GET',
			credentials: 'include',
			headers: { Accept: 'application/json' },
		})
		const json = await res.json()
		wfInput.picOptions = (json.message || []).map((r) => ({
			value: String(r.name),
			label: String(r.nama_lengkap || r.name),
		}))
	} catch (e) {
		wfInput.picOptions = []
	} finally {
		wfInput.picLoading = false
	}
}

// Validasi → suntik nilai ke doc.data (ikut tersimpan saat apply_workflow) → jalankan aksi.
async function submitWfInput() {
	if (wfInput.submitting) return
	if (wfInput.kind === 'pic') {
		if (!wfInput.pic) {
			wfInput.error = 'Silakan pilih pengguna.'
			return
		}
	} else if (!wfInput.value.trim()) {
		wfInput.error =
			wfInput.kind === 'alasan'
				? 'Alasan banding wajib diisi.'
				: 'Keterangan pembatalan wajib diisi.'
		return
	}
	wfInput.submitting = true
	wfInput.error = ''
	try {
		if (wfInput.kind === 'alasan') doc.data.alasan_banding = wfInput.value.trim()
		else if (wfInput.kind === 'cancel')
			doc.data.keterangan_cancel_approval = wfInput.value.trim()
		else if (wfInput.kind === 'pic') doc.data.banding_ke = wfInput.pic
		const action = wfInput.action
		wfInput.open = false
		await applyAction(action)
	} finally {
		wfInput.submitting = false
	}
}

onMounted(async () => {
	await refreshCsrfToken()
	// Begitu dokumen selesai di-fetch, langsung ambil transisi workflow (paralel
	// dengan meta/permlevel yang biasanya lebih lambat) → tombol Actions bawah
	// tidak muncul terlambat.
	await Promise.all([
		loadMeta(),
		doc.fetch().then(() => loadTransitions()),
		loadPermlevelAccess(),
		loadWorkflowEditMap(),
	])
	// Isi nilai field editable dari dokumen (sekaligus reset dirty).
	await syncFormFromDoc()
	// Unit internal (MOKAS): hitung ulang flag dealer untuk visibilitas motor_tarikan
	// (tanpa mengosongkan unit tersimpan), lalu aktifkan watcher dealer.
	await loadDealerMokasList()
	await syncDealerMokasFlag({ clearUnit: false })
	dealerReady.value = true
	// Semua sumber penentu visibilitas field (meta + permlevel + form) sudah siap →
	// baru tetapkan sub-tab default ("Data Nasabah").
	coreLoaded.value = true
	await nextTick()
	initActiveSubtab()
	// Elemen header & tab strip sudah ter-render → ukur tinggi untuk offset sticky.
	measureSticky()
	setupStickyObservers()
	resolveAllLinks()
	loadActivity()
	loadComments()
	loadPendukungOptions()
})
