<script setup>
import { computed, nextTick, onBeforeUnmount, onMounted, reactive, ref, watch } from 'vue'
import { useRouter } from 'vue-router'
import { refreshCsrfToken, sessionUser } from '../data/session'
import { statusPillClass as statusClass } from '../data/dataPengajuanStatus'
import { notifyError } from '../composables/toast'
import SelectMenu from '../components/SelectMenu.vue'

const router = useRouter()

// Nilai field (reactive). status mulai 'Draft' (initial state workflow Flow Kredit)
// → field mandatory_depends_on(status=="Draft") ikut wajib, sesuai Frappe.
const form = reactive({ status: 'Draft' })

// Nama Marketing = user yang login (read-only). Server controller juga set
// marketing=user_id, TAPI fetch_from marketing_full_name jalan SEBELUM itu
// (urutan save Frappe) → kalau tidak kita isi dari sini, nama di list kosong.
// Maka kita set marketing + marketing_full_name dari User Juragan user aktif.
const marketingDisplay = ref('')
async function loadMarketing() {
	const user = sessionUser()
	if (!user) return
	form.marketing = user
	marketingDisplay.value = user // fallback sementara
	try {
		const params = new URLSearchParams({ doctype: 'User Juragan', name: user })
		const res = await fetch(`/api/method/frappe.client.get?${params.toString()}`, {
			method: 'GET',
			credentials: 'include',
			cache: 'no-store',
			headers: { Accept: 'application/json' },
		})
		const doc = (await res.json())?.message
		const nama = (doc && doc.nama_lengkap) || ''
		if (nama) {
			form.marketing_full_name = nama
			marketingDisplay.value = nama
		}
		// Cabang TERISI OTOMATIS dari User Juragan marketing (persis controller desk:
		// self.cabang = User Juragan.cabang). Field cabang read-only, bukan manual.
		if (doc && doc.cabang) form.cabang = doc.cabang
	} catch (e) {
		/* biarkan fallback = email */
	}
}

// Tampilan nilai field read-only (Currency/Link/lainnya) di form create.
function readOnlyText(field) {
	const v = form[field.fieldname]
	if (v == null || v === '') return '—'
	if (field.fieldtype === 'Currency') return currencyDisplay(v)
	if (field.fieldtype === 'Link') return linkDisplay(field) || v
	return v
}

const saving = ref(false)
const saveError = ref('')

// ---- Meta doctype ----------------------------------------------------------
const metaFields = ref([])
const metaError = ref('')

// ---- Akses permlevel (persis desk) -----------------------------------------
// Sumber kebenaran = Meta.get_permlevel_access server (endpoint get_permlevel_access).
// Field pada permlevel yang TAK boleh dibaca user → disembunyikan; yang boleh baca
// tapi tak boleh tulis → read-only. Ini menyamakan visibilitas form create portal
// dengan desk (mis. Sales User hanya boleh permlevel 0; CMO 0/1/4/5 dst).
const readablePermlevels = ref(new Set([0]))
const writablePermlevels = ref(new Set([0]))
async function loadPermlevelAccess() {
	try {
		const params = new URLSearchParams({ doctype: 'Data Pengajuan' })
		const res = await fetch(
			`/api/method/juragan.api.portal.meta.get_permlevel_access?${params.toString()}`,
			{ method: 'GET', credentials: 'include', headers: { Accept: 'application/json' } }
		)
		if (!res.ok) return
		const msg = (await res.json()).message || {}
		if (Array.isArray(msg.read)) readablePermlevels.value = new Set([0, ...msg.read])
		if (Array.isArray(msg.write)) writablePermlevels.value = new Set([0, ...msg.write])
	} catch (e) {
		/* fallback aman: hanya permlevel 0 */
	}
}
function canReadPermlevel(f) {
	return readablePermlevels.value.has(f.permlevel || 0)
}
function canWritePermlevel(f) {
	return writablePermlevels.value.has(f.permlevel || 0)
}

// ---- Tab top-level (fungsi) -----------------------------------------------
// Halaman Add hanya menampilkan Data & Attachments. Activity & Comments tidak
// ada di sini karena dokumen belum tersimpan (belum ada record untuk ditautkan);
// keduanya tersedia di halaman Detail setelah data disimpan.
const TABS = [
	{
		key: 'data',
		label: 'Data',
		icon: '<rect x="3" y="3" width="18" height="18" rx="2"/><path d="M3 9h18"/><path d="M9 21V9"/>',
	},
	{
		key: 'attachments',
		label: 'Attachments',
		icon: '<path d="m21.44 11.05-9.19 9.19a6 6 0 0 1-8.49-8.49l8.57-8.57A4 4 0 1 1 18 8.84l-8.59 8.57a2 2 0 0 1-2.83-2.83l8.49-8.48"/>',
	},
]
const activeTab = ref('data')

// Semua tab yang tersisa (Data & Attachments) selalu bisa diakses.
function tabEnabled() {
	return true
}

// Sub-tab di dalam tab "Data" (= Tab Break dari meta doctype).
const activeSubtab = ref('')

// Kelas input form (isi field text-xs; tombol & heading pakai ukuran natural-nya).
const inputClass =
	'min-h-[44px] w-full rounded-md border border-gray-300 bg-white px-3 py-2 text-base text-gray-800 outline-none transition focus:border-primary focus:ring-2 focus:ring-inset focus:ring-primary/30 md:min-h-0'

// Susun tab → section → kolom → field dari meta (urut sesuai idx asli).
const dataTabs = computed(() => {
	const tabs = []
	let curTab = null
	let curSection = null
	let curCol = null
	for (const f of metaFields.value) {
		const ft = f.fieldtype
		if (ft === 'Tab Break') {
			curTab = { key: f.fieldname, label: f.label || f.fieldname, sections: [] }
			tabs.push(curTab)
			curSection = null
			curCol = null
			continue
		}
		if (!curTab) continue
		if (ft === 'Section Break') {
			curCol = []
			curSection = { label: f.label || '', depends_on: f.depends_on, columns: [curCol] }
			curTab.sections.push(curSection)
			continue
		}
		if (ft === 'Column Break') {
			if (!curSection) {
				curCol = []
				curSection = { label: '', columns: [curCol] }
				curTab.sections.push(curSection)
			} else {
				curCol = []
				curSection.columns.push(curCol)
			}
			continue
		}
		// Lewati field non-input / yang ditangani terpisah (Attach & child table →
		// dilengkapi di detail setelah dokumen dibuat).
		if (
			[
				'HTML',
				'Button',
				'Heading',
				'Fold',
				'Image',
				'Barcode',
				'Table',
				'Table MultiSelect',
				'Attach',
				'Attach Image',
			].includes(ft)
		)
			continue
		if (f.hidden) continue
		// permlevel tanpa hak baca → sembunyikan (persis form desk). Mis. Sales User
		// hanya boleh permlevel 0, jadi field nasabah/kendaraan (permlevel 1) hilang.
		if (!canReadPermlevel(f)) continue
		if (f.depends_on && !evalCondition(f.depends_on)) continue
		// Field read-only yang masih KOSONG → sembunyikan (jangan tampilkan "—").
		// Mis. `kategori_enduser` terkunci sampai status "Proses CA"; di form create
		// dokumen selalu baru, jadi cukup disembunyikan selama belum ada isinya.
		if (isFieldReadOnly(f)) {
			const v = form[f.fieldname]
			if (v == null || v === '') continue
		}
		if (!curSection) {
			curCol = []
			curSection = { label: '', columns: [curCol] }
			curTab.sections.push(curSection)
		}
		curCol.push(f)
	}
	for (const t of tabs) {
		t.sections = t.sections
			.filter((s) => evalCondition(s.depends_on))
			.map((s) => ({ ...s, columns: s.columns.filter((c) => c.length) }))
			.filter((s) => s.columns.length)
	}
	return tabs
})

// Daftar sub-tab (label) untuk strip di dalam tab "Data".
const SUBTABS = computed(() => dataTabs.value.map((t) => ({ key: t.key, label: t.label })))

const sectionsForActiveSubtab = computed(() => {
	const t = dataTabs.value.find((x) => x.key === activeSubtab.value)
	return t ? t.sections : []
})

// Field Attach (File Kredit) → dirender di tab Attachments (di-stage ke payload insert).
const attachFields = computed(() =>
	metaFields.value.filter((f) => ['Attach', 'Attach Image'].includes(f.fieldtype) && !f.hidden)
)

// Ganti sub-tab + reset scroll ke awal.
const topAnchor = ref(null)
function selectSubtab(key) {
	activeSubtab.value = key
	openDropdown.value = ''
	nextTick(() => topAnchor.value?.scrollIntoView({ block: 'start' }))
}

// Nama file dari URL (untuk tampilan link Attachment).
function fileName(url) {
	if (!url) return ''
	const clean = String(url).split('?')[0]
	return decodeURIComponent(clean.substring(clean.lastIndexOf('/') + 1)) || clean
}

// Semua field yang sedang tampil (utk validasi wajib lintas tab).
const allFields = computed(() => {
	const out = []
	for (const t of dataTabs.value)
		for (const s of t.sections) for (const c of s.columns) for (const f of c) out.push(f)
	return out
})

// ---- Helper widget ---------------------------------------------------------
function selectOptions(field) {
	return String(field.options || '')
		.split('\n')
		.map((s) => s.trim())
		.filter(Boolean)
}
function isTextarea(ft) {
	return ['Small Text', 'Text', 'Long Text', 'Code', 'Text Editor'].includes(ft)
}
function isNumberField(ft) {
	return ['Int', 'Float', 'Currency', 'Percent'].includes(ft)
}

// Evaluasi ekspresi kondisi Frappe (depends_on / mandatory_depends_on) thd form.
function evalCondition(expr) {
	if (!expr) return true
	try {
		const code = String(expr).replace(/^eval:/, '')
		const in_list = (list, item) => Array.isArray(list) && list.includes(item)
		const cint = (v) => parseInt(v, 10) || 0
		const cstr = (v) => (v == null ? '' : String(v))
		const flt = (v) => parseFloat(v) || 0
		// Shim `frappe.session.user` supaya depends_on admin-only (mis. Status Geocoding)
		// dievaluasi benar, bukan gagal → fail-open (tampil untuk semua).
		const frappe = { session: { user: sessionUser() } }
		// eslint-disable-next-line no-new-func
		return !!new Function(
			'doc',
			'in_list',
			'cint',
			'cstr',
			'flt',
			'frappe',
			`return (${code})`
		)(form, in_list, cint, cstr, flt, frappe)
	} catch (e) {
		return true
	}
}
function isFieldReqd(field) {
	if (field.reqd) return true
	return field.mandatory_depends_on ? evalCondition(field.mandatory_depends_on) : false
}

// Read-only saat create: hormati read_only statis DAN read_only_depends_on (persis
// doctype). Dokumen baru tak pernah berstatus "Proses CA", jadi field seperti
// `kategori_enduser` (read_only_depends_on: status != "Proses CA") otomatis terkunci
// di form create — hanya bisa diisi nanti di detail saat Proses CA oleh role
// berhak (permlevel 1: CMO, Credit Analyst, Pimcab, Pembanding, IT Administrator).
function isFieldReadOnly(field) {
	// Tak punya hak tulis permlevel → read-only (persis form desk).
	if (!canWritePermlevel(field)) return true
	// read_only_depends_on MENIMPA read_only statis (persis set_dependant_property desk):
	// mis. provinsi_domisili (read_only=1 + dep CA Rejected/Banding) → editable saat baru.
	if (field.read_only_depends_on) return evalCondition(field.read_only_depends_on)
	return !!field.read_only
}

// ---- Currency --------------------------------------------------------------
function formatCurrency(v) {
	const n = Number(v)
	if (v === '' || v == null || Number.isNaN(n)) return String(v ?? '')
	return new Intl.NumberFormat('id-ID', {
		minimumFractionDigits: 2,
		maximumFractionDigits: 2,
	}).format(n)
}
function currencyDisplay(v) {
	if (v === '' || v == null || Number.isNaN(Number(v))) return ''
	return `Rp ${formatCurrency(v)}`
}
function parseCurrency(str) {
	if (str == null) return ''
	const cleaned = String(str)
		.replace(/\./g, '')
		.replace(',', '.')
		.replace(/[^\d.]/g, '')
	if (cleaned === '') return ''
	const n = Number(cleaned)
	return Number.isNaN(n) ? '' : n
}
function onCurrencyBlur(field, e) {
	const n = parseCurrency(e.target.value)
	form[field.fieldname] = n
	e.target.value = currencyDisplay(n)
}

// ---- Resolusi Link (judul + dropdown searchable) ---------------------------
const linkTitleField = reactive({})
const linkTitles = reactive({})
const linkOptions = reactive({})

async function loadLinkMeta() {
	const dts = new Set()
	for (const f of metaFields.value) {
		if (f.fieldtype === 'Link' && f.options) dts.add(f.options)
	}
	await Promise.all(
		[...dts].map(async (dt) => {
			let titleField = null
			try {
				const res = await fetch(
					`/api/method/frappe.desk.form.load.getdoctype?doctype=${encodeURIComponent(
						dt
					)}`,
					{
						method: 'GET',
						credentials: 'include',
						headers: { Accept: 'application/json' },
					}
				)
				const json = await res.json()
				const docs = json.docs || json.message?.docs || []
				const meta = docs.find((x) => x.name === dt) || docs[0]
				titleField = (meta && meta.title_field) || null
				linkTitleField[dt] = titleField
			} catch (e) {
				linkTitleField[dt] = null
			}
			try {
				const flds = titleField ? ['name', titleField] : ['name']
				const lparams = new URLSearchParams({
					doctype: dt,
					fields: JSON.stringify(flds),
					limit_page_length: '101',
					order_by: 'name asc',
				})
				const lres = await fetch(
					`/api/method/frappe.client.get_list?${lparams.toString()}`,
					{
						method: 'GET',
						credentials: 'include',
						headers: { Accept: 'application/json' },
					}
				)
				const ljson = await lres.json()
				const recs = ljson.message || []
				if (recs.length && recs.length <= 100) {
					linkOptions[dt] = recs.map((r) => ({
						value: String(r.name),
						label: (titleField && r[titleField]) || String(r.name),
					}))
				}
			} catch (e) {
				// abaikan → fallback ke fetch saat dibuka
			}
		})
	)
}

function linkDisplay(field) {
	const v = form[field.fieldname]
	if (!v) return ''
	const opts = linkOptions[field.options]
	if (opts) {
		const cur = opts.find((o) => String(o.value).toLowerCase() === String(v).toLowerCase())
		if (cur) return cur.label
	}
	const t = linkTitles[`${field.options}:${v}`]
	return t !== undefined ? t : v
}

const openDropdown = ref('')
// Arah buka dropdown: true = ke atas (saat ruang di bawah trigger tidak cukup,
// mis. field terakhir "Data Kendaraan" yang tertutup tombol Save).
const dropUp = ref(false)
const linkSearch = ref('')
const linkResults = ref([])
const linkSearchLoading = ref(false)

// Filter bawaan Link dari Frappe (`link_filters`) → array [field, op, value] utk
// dikirim ke get_list, supaya opsi yang tampil SAMA dengan desk (mis. hanya data
// `aktif=1`). Tanpa ini, opsi non-aktif ikut muncul lalu ditolak server (mis.
// controller Data Pengajuan me-null `model` non-aktif → "Value missing: Model").
// Kondisi dinamis (eval:/referensi doc) dilewati karena tak bisa dievaluasi di klien.
// Cascade filter domisili — meniru client script desk "Dynamic Select Domisili".
// provinsi_domisili fixed "Kepulauan Riau" (kode 21): Kota difilter provinsi,
// Kecamatan difilter kota terpilih, Kelurahan difilter kecamatan (+kota guard)
// terpilih. Nilai '' saat parent belum dipilih → hasil kosong (paksa urutan isi).
const PROV_CODE_DOMISILI = '21' // Kepulauan Riau
const domisiliFilters = {
	kota_domisili: () => [['kode_provinsi', '=', PROV_CODE_DOMISILI]],
	kecamatan_domisili: () => [['kode_kab_kota', '=', form.kota_domisili || '']],
	kelurahan_domisili: () => [
		['kode_kecamatan', '=', form.kecamatan_domisili || ''],
		['kode_kab_kota', '=', form.kota_domisili || ''],
	],
	kota_domisili_pps: () => [['kode_provinsi', '=', PROV_CODE_DOMISILI]],
	kecamatan_domisili_pps: () => [['kode_kab_kota', '=', form.kota_domisili_pps || '']],
	kelurahan_domisili_pps: () => [
		['kode_kecamatan', '=', form.kecamatan_domisili_pps || ''],
		['kode_kab_kota', '=', form.kota_domisili_pps || ''],
	],
}
// Parent berubah → kosongkan turunannya (spt set_value(null) di client script desk).
const domisiliChildren = {
	kota_domisili: ['kecamatan_domisili', 'kelurahan_domisili'],
	kecamatan_domisili: ['kelurahan_domisili'],
	kota_domisili_pps: ['kecamatan_domisili_pps', 'kelurahan_domisili_pps'],
	kecamatan_domisili_pps: ['kelurahan_domisili_pps'],
}

function linkFilters(field) {
	const out = []
	const push = (f, op, v) => {
		const isDyn = typeof v === 'string' && /^eval:|^doc\./.test(v.trim())
		if (!isDyn) {
			out.push([f, op, v])
			return
		}
		// Resolusi nilai DINAMIS terhadap form (mis. "eval: doc.tenor" → nilai tenor
		// terpilih) supaya filter ikut nilai form — mis. Skema Pinjaman hanya tenor
		// yang dipilih. Belum ada nilai (tenor belum dipilih) → filter dilewati.
		let val
		try {
			const s = v.trim()
			// eslint-disable-next-line no-new-func
			val = s.startsWith('eval:')
				? new Function('doc', `return (${s.slice(5)})`)(form)
				: form[s.slice(4)]
		} catch (e) {
			val = undefined
		}
		if (val === undefined || val === null || val === '') return
		out.push([f, op, val])
	}
	// Filter bawaan Link dari Frappe (`link_filters`).
	let raw = field.link_filters
	if (raw) {
		try {
			if (typeof raw === 'string') raw = JSON.parse(raw)
		} catch (e) {
			raw = null
		}
		if (Array.isArray(raw)) {
			for (const c of raw) {
				if (!Array.isArray(c)) continue
				if (c.length === 4) push(c[1], c[2], c[3])
				else if (c.length === 3) push(c[0], c[1], c[2])
			}
		} else if (raw && typeof raw === 'object') {
			for (const [k, v] of Object.entries(raw)) push(k, '=', v)
		}
	}
	// Cascade domisili (tak ada di link_filters doctype; disetel via client script desk).
	const dom = domisiliFilters[field.fieldname]
	if (dom) out.push(...dom())
	return out
}

function optionMatch(opt, field) {
	const v = form[field.fieldname]
	if (v == null || v === '') return false
	return String(opt.value).toLowerCase() === String(v).toLowerCase()
}
// Perkiraan tinggi panel dropdown (search box + list max-h-56). Dipakai untuk
// memutuskan buka ke atas / ke bawah agar tidak tertutup tombol Save.
const DROPDOWN_EST_HEIGHT = 300
function toggleLinkDropdown(field, event) {
	if (openDropdown.value === field.fieldname) {
		openDropdown.value = ''
		return
	}
	// Tentukan arah: kalau ruang di bawah trigger kurang DAN ruang di atas lebih
	// lega, buka ke atas. Ini yang mencegah dropdown menutupi tombol Save.
	const rect = event?.currentTarget?.getBoundingClientRect?.()
	if (rect) {
		const spaceBelow = window.innerHeight - rect.bottom
		const spaceAbove = rect.top
		dropUp.value = spaceBelow < DROPDOWN_EST_HEIGHT && spaceAbove > spaceBelow
	} else {
		dropUp.value = false
	}
	openDropdown.value = field.fieldname
	linkSearch.value = ''
	// Field dgn link_filters / motor_tarikan → selalu fetch (jangan pakai cache generik).
	const opts =
		field.fieldname === 'motor_tarikan' || linkFilters(field).length
			? null
			: linkOptions[field.options]
	if (opts) linkResults.value = opts
	else fetchLinkResults(field, '')
}
async function fetchLinkResults(field, query) {
	// Unit internal → query terfilter dealer (get_mokas_unit_query), bukan get_list.
	if (field.fieldname === 'motor_tarikan') return fetchMokasUnits(query)
	const dt = field.options
	const titleField = linkTitleField[dt]
	linkSearchLoading.value = true
	linkResults.value = []
	try {
		const flds = titleField ? ['name', titleField] : ['name']
		const params = new URLSearchParams({
			doctype: dt,
			fields: JSON.stringify(flds),
			limit_page_length: '20',
			order_by: 'name asc',
		})
		const lf = linkFilters(field)
		if (lf.length) params.set('filters', JSON.stringify(lf))
		if (query) {
			const ors = [['name', 'like', `%${query}%`]]
			if (titleField) ors.push([titleField, 'like', `%${query}%`])
			params.set('or_filters', JSON.stringify(ors))
		}
		const res = await fetch(`/api/method/frappe.client.get_list?${params.toString()}`, {
			method: 'GET',
			credentials: 'include',
			headers: { Accept: 'application/json' },
		})
		const json = await res.json()
		const recs = json.message || []
		linkResults.value = recs.map((r) => ({
			value: String(r.name),
			label: (titleField && r[titleField]) || String(r.name),
		}))
	} catch (e) {
		linkResults.value = []
	} finally {
		linkSearchLoading.value = false
	}
}
let linkSearchTimer = null
function onLinkSearch(field) {
	const q = linkSearch.value.trim()
	const opts =
		field.fieldname === 'motor_tarikan' || linkFilters(field).length
			? null
			: linkOptions[field.options]
	if (opts) {
		const ql = q.toLowerCase()
		linkResults.value = ql
			? opts.filter(
					(o) =>
						o.label.toLowerCase().includes(ql) ||
						String(o.value).toLowerCase().includes(ql)
			  )
			: opts
		return
	}
	clearTimeout(linkSearchTimer)
	linkSearchTimer = setTimeout(() => fetchLinkResults(field, q), 300)
}
// Tiru perilaku `fetch_from` Frappe: saat sebuah Link berubah, langsung isi
// field turunannya dari dokumen tertaut TANPA perlu save (persis form desk).
// Mis. pinjam ← skema_pinjaman.pinjaman, angsuran ← skema_pinjaman.angsuran.
async function applyFetchFrom(linkField, value) {
	const prefix = `${linkField.fieldname}.`
	const targets = metaFields.value.filter(
		(f) => typeof f.fetch_from === 'string' && f.fetch_from.startsWith(prefix)
	)
	if (!targets.length) return
	// Link dikosongkan → kosongkan juga field turunannya.
	if (!value) {
		for (const t of targets) form[t.fieldname] = null
		return
	}
	const sourceFields = targets.map((t) => t.fetch_from.slice(prefix.length))
	try {
		const params = new URLSearchParams({
			doctype: linkField.options,
			filters: JSON.stringify({ name: value }),
			fieldname: JSON.stringify(sourceFields),
		})
		const res = await fetch(`/api/method/frappe.client.get_value?${params.toString()}`, {
			method: 'GET',
			credentials: 'include',
			headers: { Accept: 'application/json' },
		})
		if (!res.ok) return
		const data = (await res.json())?.message || {}
		for (const t of targets) {
			const src = t.fetch_from.slice(prefix.length)
			if (src in data) form[t.fieldname] = data[src]
		}
	} catch (e) {
		/* abaikan — nilai tetap akan ikut terisi server saat save (fallback) */
	}
}

function selectLink(field, value, label) {
	const prev = form[field.fieldname]
	form[field.fieldname] = value
	if (label != null) linkTitles[`${field.options}:${value}`] = label
	openDropdown.value = ''
	// Isi otomatis field ber-fetch_from (mis. Pinjaman & Angsuran dari Skema Pinjaman).
	applyFetchFrom(field, value)
	// Cascade domisili: parent berubah → kosongkan turunannya (spt client script desk).
	if (prev !== value) {
		const children = domisiliChildren[field.fieldname]
		if (children) for (const c of children) form[c] = null
	}
}

